```go
package matrix

import (
	"errors"
	"fmt"
)

// ErrNotSquare is returned when the input matrix is not square.
var ErrNotSquare = errors.New("matrix must be square")

// Rotate90Clockwise rotates m 90 degrees clockwise, in place.
//
// m must be square: every row must have len(m) elements. If m is not square,
// Rotate90Clockwise returns ErrNotSquare and leaves m unchanged. A nil or
// empty matrix is a no-op.
//
// Implementation notes:
//   - It transposes the matrix, then reverses each row.
//   - The transpose loop only visits the upper triangle (j > i). Visiting the
//     whole matrix would swap each pair twice and undo the transpose.
//   - Validation happens before mutation so an invalid matrix is never
//     partially rotated.
//
// Complexity: O(n^2) time and O(1) extra space on the success path.
func Rotate90Clockwise[T any](m [][]T) error {
	n := len(m)
	if n == 0 {
		return nil
	}

	for i := range m {
		if len(m[i]) != n {
			return fmt.Errorf(
				"%w: row %d has length %d, want %d",
				ErrNotSquare, i, len(m[i]), n,
			)
		}
	}

	// Transpose: swap across the main diagonal.
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			m[i][j], m[j][i] = m[j][i], m[i][j]
		}
	}

	// Reverse each row to finish the clockwise rotation.
	for i := 0; i < n; i++ {
		for left, right := 0, n-1; left < right; left, right = left+1, right-1 {
			m[i][left], m[i][right] = m[i][right], m[i][left]
		}
	}

	return nil
}
```

Example:

```go
m := [][]int{
	{1, 2, 3},
	{4, 5, 6},
	{7, 8, 9},
}

if err := matrix.Rotate90Clockwise(m); err != nil {
	// handle invalid input
}

// m is now:
// [][]int{
// 	{7, 4, 1},
// 	{8, 5, 2},
// 	{9, 6, 3},
// }
```

If you only need `int` matrices, replace `[T any](m [][]T)` with `(m [][]int)`. For counterclockwise rotation, transpose and then reverse the row order instead of reversing each row.

