```ts
// dijkstra.ts

export interface Edge<T> {
  to: T;
  weight: number;
}

export type Graph<T> = Map<T, Edge<T>[]>;

/**
 * Simple binary min-heap.
 * Comparator should return a negative number when `a` should come before `b`.
 */
export class MinHeap<T> {
  private heap: T[] = [];

  constructor(private readonly compare: (a: T, b: T) => number) {}

  get size(): number {
    return this.heap.length;
  }

  isEmpty(): boolean {
    return this.heap.length === 0;
  }

  peek(): T | undefined {
    return this.heap[0];
  }

  push(value: T): void {
    this.heap.push(value);
    this.siftUp(this.heap.length - 1);
  }

  pop(): T | undefined {
    if (this.heap.length === 0) return undefined;

    const top = this.heap[0];
    const last = this.heap.pop()!;

    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.siftDown(0);
    }

    return top;
  }

  private siftUp(index: number): void {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);

      if (this.compare(this.heap[index], this.heap[parent]) >= 0) break;

      [this.heap[index], this.heap[parent]] = [
        this.heap[parent],
        this.heap[index],
      ];
      index = parent;
    }
  }

  private siftDown(index: number): void {
    const length = this.heap.length;

    while (true) {
      const left = index * 2 + 1;
      const right = index * 2 + 2;
      let smallest = index;

      if (
        left < length &&
        this.compare(this.heap[left], this.heap[smallest]) < 0
      ) {
        smallest = left;
      }

      if (
        right < length &&
        this.compare(this.heap[right], this.heap[smallest]) < 0
      ) {
        smallest = right;
      }

      if (smallest === index) break;

      [this.heap[index], this.heap[smallest]] = [
        this.heap[smallest],
        this.heap[index],
      ];
      index = smallest;
    }
  }
}

/**
 * Dijkstra's algorithm using an adjacency list and a binary min-heap.
 *
 * Returns a map of reachable nodes to their shortest distance from `start`.
 * The source is always included with distance 0, even if it has no entry in
 * the graph.
 *
 * Throws if the graph contains negative or non-finite edge weights.
 */
export function dijkstra<T>(graph: Graph<T>, start: T): Map<T, number> {
  // Dijkstra requires finite, non-negative weights.
  for (const edges of graph.values()) {
    for (const edge of edges) {
      if (!Number.isFinite(edge.weight) || edge.weight < 0) {
        throw new Error(
          `Dijkstra requires finite, non-negative edge weights. Received: ${edge.weight}`,
        );
      }
    }
  }

  const distances = new Map<T, number>();
  const heap = new MinHeap<{ node: T; distance: number }>(
    (a, b) => a.distance - b.distance,
  );

  distances.set(start, 0);
  heap.push({ node: start, distance: 0 });

  while (!heap.isEmpty()) {
    const current = heap.pop()!;
    const knownDistance = distances.get(current.node);

    // Lazy deletion: skip stale heap entries.
    if (knownDistance === undefined || current.distance !== knownDistance) {
      continue;
    }

    const edges = graph.get(current.node) ?? [];

    for (const edge of edges) {
      const nextDistance = current.distance + edge.weight;
      const previousDistance = distances.get(edge.to);

      if (
        previousDistance === undefined ||
        nextDistance < previousDistance
      ) {
        distances.set(edge.to, nextDistance);
        heap.push({ node: edge.to, distance: nextDistance });
      }
    }
  }

  return distances;
}
