```ts
// dijkstra.test.ts

import { dijkstra, Graph } from './dijkstra';

describe('dijkstra', () => {
  it('returns source distance 0 for an empty graph', () => {
    const graph: Graph<string> = new Map();

    expect(dijkstra(graph, 'A')).toEqual(new Map([['A', 0]]));
  });

  it('handles a single node with no outgoing edges', () => {
    const graph: Graph<string> = new Map([['A', []]]);

    expect(dijkstra(graph, 'A')).toEqual(new Map([['A', 0]]));
  });

  it('returns source distance 0 when source is not a graph key', () => {
    const graph: Graph<string> = new Map([
      ['A', [{ to: 'B', weight: 1 }]],
    ]);

    expect(dijkstra(graph, 'Z')).toEqual(new Map([['Z', 0]]));
  });

  it('finds shortest distances and omits unreachable nodes', () => {
    const graph: Graph<string> = new Map([
      ['A', [{ to: 'B', weight: 4 }]],
      ['B', [{ to: 'C', weight: 2 }]],
      ['D', [{ to: 'E', weight: 1 }]],
      ['E', []],
    ]);

    expect(dijkstra(graph, 'A')).toEqual(
      new Map([
        ['A', 0],
        ['B', 4],
        ['C', 6],
      ]),
    );
  });

  it('chooses an indirect shorter path over a direct longer path', () => {
    const graph: Graph<string> = new Map([
      ['A', [
        { to: 'B', weight: 10 },
        { to: 'C', weight: 1 },
      ]],
      ['C', [{ to: 'B', weight: 2 }]],
      ['B', []],
    ]);

    const distances = dijkstra(graph, 'A');

    expect(distances.get('B')).toBe(3);
    expect(distances.get('C')).toBe(1);
  });

  it('handles zero-weight edges', () => {
    const graph: Graph<string> = new Map([
      ['A', [{ to: 'B', weight: 0 }]],
      ['B', [{ to: 'C', weight: 0 }]],
      ['C', []],
    ]);

    expect(dijkstra(graph, 'A')).toEqual(
      new Map([
        ['A', 0],
        ['B', 0],
        ['C', 0],
      ]),
    );
  });

  it('uses the smallest duplicate edge weight', () => {
    const graph: Graph<string> = new Map([
      ['A', [
        { to: 'B', weight: 5 },
        { to: 'B', weight: 2 },
      ]],
      ['B', []],
    ]);

    expect(dijkstra(graph, 'A').get('B')).toBe(2);
  });

  it('handles cycles without looping forever', () => {
    const graph: Graph<string> = new Map([
      ['A', [{ to: 'B', weight: 1 }]],
      ['B', [{ to: 'C', weight: 1 }]],
      ['C', [{ to: 'A', weight: 1 }]],
    ]);

    expect(dijkstra(graph, 'A')).toEqual(
      new Map([
        ['A', 0],
        ['B', 1],
        ['C', 2],
      ]),
    );
  });

  it('throws on negative edge weights', () => {
    const graph: Graph<string> = new Map([
      ['A', [{ to: 'B', weight: -1 }]],
      ['B', []],
    ]);

    expect(() => dijkstra(graph, 'A')).toThrow(
      /non-negative edge weights/,
    );
  });

  it('throws on non-finite edge weights', () => {
    const graph: Graph<string> = new Map([
      ['A', [{ to: 'B', weight: Infinity }]],
      ['B', []],
    ]);

    expect(() => dijkstra(graph, 'A')).toThrow(
      /finite, non-negative edge weights/,
    );
  });

  it('works with numeric node identities', () => {
    const graph: Graph<number> = new Map([
      [1, [
        { to: 2, weight: 7 },
        { to: 3, weight: 1 },
      ]],
      [2, []],
      [3, [{ to: 2, weight: 2 }]],
    ]);

    expect(dijkstra(graph, 1)).toEqual(
      new Map([
        [1, 0],
        [2, 3],
        [3, 1],
      ]),
    );
  });
});
