# Skiplist in Rust

Here's a complete skiplist implementation using an arena-based approach (`Vec<Node>`) to avoid fighting the borrow checker with `Box`/`Rc<RefCell<>>`. It supports `insert`, `delete`, and `search`, plus thorough unit tests.

```rust
const MAX_LEVEL: usize = 16;

struct Node<T> {
    value: Option<T>,
    forward: Vec<Option<usize>>,
}

pub struct SkipList<T: Ord + Clone> {
    nodes: Vec<Node<T>>,
    level: usize,       // highest level index currently in use (0-based)
    rng_state: u64,
}

impl<T: Ord + Clone> SkipList<T> {
    pub fn new() -> Self {
        let head = Node {
            value: None,
            forward: vec![None; MAX_LEVEL],
        };
        SkipList {
            nodes: vec![head],
            level: 0,
            rng_state: 0x9E3779B97F4A7C15,
        }
    }

    fn next_rand(&mut self) -> u64 {
        // xorshift64*
        let mut x = self.rng_state;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.rng_state = x;
        x.wrapping_mul(0x2545F4914F6CDD1D)
    }

    /// Returns level count in 1..=MAX_LEVEL.
    fn random_level(&mut self) -> usize {
        let mut lvl = 1;
        while lvl < MAX_LEVEL && (self.next_rand() & 1) == 0 {
            lvl += 1;
        }
        lvl
    }

    pub fn search(&self, value: &T) -> bool {
        let mut x = 0usize;
        for i in (0..=self.level).rev() {
            while let Some(y) = self.nodes[x].forward[i] {
                if self.nodes[y].value.as_ref().unwrap() < value {
                    x = y;
                } else {
                    break;
                }
            }
        }
        match self.nodes[x].forward[0] {
            Some(y) => self.nodes[y].value.as_ref() == Some(value),
            None => false,
        }
    }

    pub fn insert(&mut self, value: T) {
        let mut update = [0usize; MAX_LEVEL];
        let mut x = 0usize;

        for i in (0..=self.level).rev() {
            while let Some(y) = self.nodes[x].forward[i] {
                if self.nodes[y].value.as_ref().unwrap() < &value {
                    x = y;
                } else {
                    break;
                }
            }
            update[i] = x;
        }

        // Reject duplicates (or you could update; here we no-op).
        if let Some(next) = self.nodes[update[0]].forward[0] {
            if self.nodes[next].value.as_ref() == Some(&value) {
                return;
            }
        }

        let new_level = self.random_level();
        if new_level - 1 > self.level {
            for i in (self.level + 1)..new_level {
                update[i] = 0;
            }
            self.level = new_level - 1;
        }

        let new_idx = self.nodes.len();
        self.nodes.push(Node {
            value: Some(value),
            forward: vec![None; new_level],
        });

        for i in 0..new_level {
            let next = self.nodes[update[i]].forward[i];
            self.nodes[new_idx].forward[i] = next;
            self.nodes[update[i]].forward[i] = Some(new_idx);
        }
    }

    pub fn delete(&mut self, value: &T) -> bool {
        let mut update = [0usize; MAX_LEVEL];
        let mut x = 0usize;

        for i in (0..=self.level).rev() {
            while let Some(y) = self.nodes[x].forward[i] {
                if self.nodes[y].value.as_ref().unwrap() < value {
                    x = y;
                } else {
                    break;
                }
            }
            update[i] = x;
        }

        let target = match self.nodes[update[0]].forward[0] {
            Some(t) if self.nodes[t].value.as_ref() == Some(value) => t,
            _ => return false,
        };

        for i in 0..=self.level {
            if self.nodes[update[i]].forward[i] == Some(target) {
                self.nodes[update[i]].forward[i] = self.nodes[target].forward[i];
            } else {
                break;
            }
        }

        // Drop the stored value to free memory; node itself stays in arena.
        self.nodes[target].value = None;
        self.nodes[target].forward.clear();

        // Shrink the top level if it became empty.
        while self.level > 0 && self.nodes[0].forward[self.level].is_none() {
            self.level -= 1;
        }

        true
    }

    pub fn len(&self) -> usize {
        // Traverse level 0 and count live nodes.
        let mut count = 0;
        let mut x = 0;
        while let Some(y) = self.nodes[x].forward[0] {
            count += 1;
            x = y;
        }
        count
    }
}
```

