#define RETRY_H

#include <stdbool.h>
#include <stdint.h>

/* Return values from the work function. */
typedef enum {
    RETRY_OK   = 0,  /* Permanent success — stop.            */
    RETRY_FAIL = 1,  /* Permanent failure — stop, return it. */
    RETRY_MORE = 2,  /* Transient — try again.               */
} retry_status;

/* Return values from retry_with_backoff. */
typedef enum {
    RETRY_EXHAUSTED = -2,  /* Ran out of attempts; last status was RETRY_MORE. */
    RETRY_ABORTED   = -1,  /* Work called back with RETRY_FAIL, or nanosleep failed. */
    RETRY_SUCCEEDED =  0,  /* Work finally returned RETRY_OK.                  */
} retry_result;

typedef retry_status (*retry_work_fn)(void *ctx, unsigned attempt);

typedef struct {
    unsigned        max_attempts;  /* Total attempts, including the first.    */
    uint64_t        base_delay_ns; /* First backoff before jitter.            */
    uint64_t        max_delay_ns;  /* Ceiling for any single sleep.           */
    /* Li'l trick: seed 0 means "use clock_gettime". */
    uint64_t        rng_seed;
    /* Optional: return true to stop retrying (e.g. shutdown flip). */
    bool          (*should_stop)(void *ctx);
} retry_opts;

retry_result retry_with_backoff(const retry_opts *opts,
                                retry_work_fn     work,
                                void             *ctx);

#endif
```

```c
// retry.c
#define _POSIX_C_SOURCE 200809L
#include "retry.h"

#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>

/* ---- xorshift64*: cheap, thread-local, good enough for jitter ----
 *
 * NOTE: We deliberately do NOT use rand()/random(). Both share global
 * state, which means two threads retrying concurrently will interleave
 * seeds and in the worst case produce correlated jitter. A per-call
 * xorshift state avoids a lock with no means of cross-thread interference.
 */
static uint64_t xs64_next(uint64_t *s) {
    uint64_t x = *s;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    *s = x;
    return x * 0x2545F4914F6CDD1DULL;
}

static uint64_t seed_from_clock(void) {
    struct timespec ts;
    /* NOTE: assumes CLOCK_MONOTONIC works. If it doesn't, fall back. */
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0x9E3779B97F4A7C15ULL;
    }
    uint64_t s = (uint64_t)ts.tv_sec ^ ((uint64_t)ts.tv_nsec << 32);
    /* Mix in pointer address of a stack var for extra entropy across
       forked processes that inherited the same clock. */
    uintptr_t mix = (uintptr_t)&ts;
    s ^= (uint64_t)mix;
    return s ? s : 0x9E3779B97F4A7C15ULL;
}

/* Saturating multiply: base << attempt can overflow on long retries. */
static uint64_t sat_mul(uint64_t a, uint64_t b) {
    if (a == 0 || b == 0) return 0;
    if (a > UINT64_MAX / b) return UINT64_MAX;
    return a * b;
}

/* Sleep for ns nanoseconds, restarting on EINTR so a signal storm can't
   cause an early wake that collapses the backoff. Returns false on a
   non-EINTR clock error. */
static bool sleep_ns(uint64_t ns) {
    struct timespec req = {
        .tv_sec  = (time_t)(ns / 1000000000ULL),
        .tv_nsec = (long)(ns % 1000000000ULL),
    };
    struct timespec rem;
    while (nanosleep(&req, &rem) != 0) {
        if (errno != EINTR) return false;
        req = rem; /* Resume remaining time. */
    }
    return true;
}

retry_result retry_with_backoff(const retry_opts *opts,
                                retry_work_fn     work,
                                void             *ctx)
{
    if (!opts || !work || opts->max_attempts == 0) return RETRY_ABORTED;

    uint64_t rng = opts->rng_seed ? opts->rng_seed : seed_from_clock();

    /* Attempt numbering: 0-based. First retry delay = base * 2^0 = base. */
    for (unsigned attempt = 0; attempt < opts->max_attempts; ++attempt) {
        if (opts->should_stop && opts->should_stop(ctx)) return RETRY_ABORTED;

        retry_status st = work(ctx, attempt);
        if (st == RETRY_OK)   return RETRY_SUCCEEDED;
        if (st == RETRY_FAIL) return RETRY_ABORTED;
        /* st == RETRY_MORE: fall through. */

        /* Don't sleep after the last attempt — wasted latency. */
        if (attempt + 1 == opts->max_attempts) break;

        /* Exponential cap: base * 2^attempt, clamped to max_delay.
         * NOTE: sat_mul prevents UB on shifts when attempt >= 64. We
         * clamp *after* the multiplication rather than shifting, which
         * would be UB for attempt >= 64 on 64-bit types. */
        uint64_t raw = sat_mul(opts->base_delay_ns, (uint64_t)1 << (attempt < 63 ? attempt : 63));
        uint64_t cap = raw < opts->max_delay_ns ? raw : opts->max_delay_ns;

        /* Full jitter: uniform in [0, cap]. If cap is 0, no sleep.
         * NOTE: (cap + 1) overflows when cap == UINT64_MAX. Guard. */
        uint64_t delay = 0;
        if (cap > 0) {
            uint64_t span = (cap == UINT64_MAX) ? UINT64_MAX : (cap + 1);
            /* Rejection-free: modulo bias is trivial at these magnitudes
               and irrelevant for jitter use. */
            delay = xs64_next(&rng) % span;
        }

        if (delay > 0 && !sleep_ns(delay)) return RETRY_ABORTED;
    }

    return RETRY_EXHAUSTED;
}
```

## Key design notes

**Full jitter, not "decorrelated".** `sleep = U(uniform, 0, base * 2^attempt)` capped. This is the AWS-recommended strategy for both good throughput and least contention during recovery stampedes. If you want *decorrelated* jitter instead, replace the modulo with `sleep = U(base, prev_sleep * 3)` — but you'll need to thread the previous delay through, which is why the API only exposes the simpler variant.

**Per-call RNG state.** Two threads retrying at the same time must not consume a shared counter, otherwise their jitter correlates and the thundering-herd protection is lost. xorshift64* is fine here — it's not cryptographic, and nothing security-relevant depends on it.

**EINTR handling matters.** A production service frequently receives signals (SIGHUP for config reload, SIGTERM). A naive `nanosleep` returns early on those, collapsing your carefully-computed backoff to near-zero. The loop resumes with the *remaining* time via `rem`, so the total sleep still matches intent.

**Overflow guards.** `base << attempt` overflows for `attempt >= 64` (UB) and even earlier for large bases. We use saturating multiply and clamp to `max_delay_ns`. The `cap + 1` overflow matters when callers set `max_delay_ns == UINT64_MAX`, which people do more often than you'd think.

**`should_stop` callback.** The single most useful addition for a long-lived daemon: lets a SIGTERM handler flip a flag and abort retries quickly instead of making a shutdown wait out a 30s backoff. Wire it up.

**Attempt counting.** `max_attempts` counts the *initial* call. `max_attempts = 1` means "call once, no retry." This aligns with how most retry libraries (Go's `avast/retry-go`, Python's `tenacity`) count, which reduces surprise for new contributors.

## Example usage

```c
static retry_status try_connect(void *ctx, unsigned attempt) {
    if (connect(fd, addr, addrlen) == 0) return RETRY_OK;
    if (errno == EINPROGRESS || errno == ECONNREFUSED) return RETRY_MORE;
    return RETRY_FAIL;  /* Auth failure, bad address, etc. */
}

retry_opts opts = {
    .max_attempts  = 5,
    .base_delay_ns = 50ULL * 1000 * 1000,      // 50ms
    .max_delay_ns  = 2ULL  * 1000 * 1000 * 1000, // 2s cap
    .should_stop   = is_shutting_down,
};
retry_result r = retry_with_backoff(&opts, try_connect, &conn_state);
```

Total worst-case wall time: `50 + 100 + 200 + 400 + 800ms = 1.55s` (without jitter), capped by `max_delay_ns` if you set it lower.

```ts
type Op = "+" | "-" | "*" | "/";

type Token =
  | { type: "num"; value: number }
  | { type: "op"; value: Op }
  | { type: "lp" }
  | { type: "rp" };

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < src.length) {
    const c = src[i];

    if (/\s/.test(c)) {
      i++;
      continue;
    }

    if ((c >= "0" && c <= "9") || c === ".") {
      let j = i;
      while (j < src.length && /[0-9.]/.test(src[j])) j++;

      const raw = src.slice(i, j);
      if (!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw)) {
        throw new Error(`Bad number: ${raw}`);
      }

      tokens.push({ type: "num", value: Number(raw) });
      i = j;
      continue;
    }

    if (c === "+" || c === "-" || c === "*" || c === "/") {
      tokens.push({ type: "op", value: c });
      i++;
      continue;
    }

    if (c === "(") {
      tokens.push({ type: "lp" });
      i++;
      continue;
    }

    if (c === ")") {
      tokens.push({ type: "rp" });
      i++;
      continue;
    }

    throw new Error(`Unexpected character: ${c}`);
  }

  return tokens;
}

export function evaluate(expr: string): number {
  const tokens = tokenize(expr);
  let i = 0;

  const peek = () => tokens[i];

  const isOp = (
    t: Token | undefined,
    ops: Op[]
  ): t is { type: "op"; value: Op } =>
    !!t && t.type === "op" && ops.includes(t.value);

  const eat = (type: Token["type"]): Token => {
    const t = tokens[i++];
    if (!t || t.type !== type) throw new Error(`Expected ${type}`);
    return t;
  };

  function parsePrimary(): number {
    if (isOp(peek(), ["+", "-"])) {
      const op = (tokens[i++] as { type: "op"; value: Op }).value;
      const value = parsePrimary();
      return op === "-" ? -value : value;
    }

    const t = peek();

    if (t?.type === "num") {
      i++;
      return t.value;
    }

    if (t?.type === "lp") {
      i++;
      const value = parseExpr();
      eat("rp");
      return value;
    }

    throw new Error("Expected number or '('");
  }

  function parseTerm(): number {
    let value = parsePrimary();

    while (isOp(peek(), ["*", "/"])) {
      const op = (tokens[i++] as { type: "op"; value: Op }).value;
      const rhs = parsePrimary();
      value = op === "*" ? value * rhs : value / rhs;
    }

    return value;
  }

  function parseExpr(): number {
    let value = parseTerm();

    while (isOp(peek(), ["+", "-"])) {
      const op = (tokens[i++] as { type: "op"; value: Op }).value;
      const rhs = parseTerm();
      value = op === "+" ? value + rhs : value - rhs;
    }

    return value;
  }

  const result = parseExpr();

  if (i !== tokens.length) throw new Error("Unexpected trailing token");

  return result;
}
```

Two ways it could fail under load:

1. **Stack exhaustion on deeply nested input**  
   The recursive-descent parser recurses for every parenthesis or unary operator. A malicious or accidental expression like `((((...1...))))` can exceed the JS call stack and throw `RangeError: Maximum call stack size exceeded`, potentially crashing a worker/process if unhandled.

2. **Event-loop starvation and memory pressure from unbounded synchronous work**  
   Tokenization and evaluation are synchronous and have no input-size, depth, or time limits. A burst of very large expressions can block the Node.js event loop, allocate large token arrays, increase latency for all requests, and exhaust memory under concurrency.

