package editdistance

import "fmt"

// OpKind describes a single operation in an edit script.
type OpKind int

const (
	Match OpKind = iota
	Insert
	Delete
	Substitute
)

func (k OpKind) String() string {
	switch k {
	case Match:
		return "match"
	case Insert:
		return "insert"
	case Delete:
		return "delete"
	case Substitute:
		return "substitute"
	default:
		return "unknown"
	}
}

// EditOp is one step in an alignment/edit script.
//
// A script is ordered from left to right. Applying it to the source string
// produces the target string:
//
//   - Match:      append To (or From; they are equal)
//   - Insert:     append To
//   - Delete:     append nothing
//   - Substitute: append To
type EditOp struct {
	Kind OpKind
	From rune // source rune; 0 for Insert
	To   rune // target rune; 0 for Delete
}

func (op EditOp) String() string {
	switch op.Kind {
	case Match:
		return fmt.Sprintf("match(%q)", op.From)
	case Insert:
		return fmt.Sprintf("insert(%q)", op.To)
	case Delete:
		return fmt.Sprintf("delete(%q)", op.From)
	case Substitute:
		return fmt.Sprintf("substitute(%q->%q)", op.From, op.To)
	default:
		return "unknown"
	}
}

// EditDistance computes the Levenshtein edit distance between a and b,
// together with an edit script that transforms a into b.
//
// Insertions, deletions, and substitutions all have cost 1.
// The function operates on Unicode code points (runes), not raw bytes.
func EditDistance(a, b string) (int, []EditOp) {
	ar := []rune(a)
	br := []rune(b)

	n, m := len(ar), len(br)

	// dp[i][j] is the edit distance between ar[:i] and br[:j].
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}

	for i := 0; i <= n; i++ {
		dp[i][0] = i
	}
	for j := 0; j <= m; j++ {
		dp[0][j] = j
	}

	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if ar[i-1] == br[j-1] {
				dp[i][j] = dp[i-1][j-1]
				continue
			}

			del := dp[i-1][j] + 1
			ins := dp[i][j-1] + 1
			sub := dp[i-1][j-1] + 1

			dp[i][j] = min3(del, ins, sub)
		}
	}

	// Backtrack from dp[n][m] to construct the edit script.
	ops := make([]EditOp, 0, max(n, m))
	i, j := n, m

	for i > 0 || j > 0 {
		if i > 0 && j > 0 && ar[i-1] == br[j-1] && dp[i][j] == dp[i-1][j-1] {
			ops = append(ops, EditOp{
				Kind: Match,
				From: ar[i-1],
				To:   br[j-1],
			})
			i--
			j--
			continue
		}

		if i > 0 && j > 0 && dp[i][j] == dp[i-1][j-1]+1 {
			ops = append(ops, EditOp{
				Kind: Substitute,
				From: ar[i-1],
				To:   br[j-1],
			})
			i--
			j--
			continue
		}

		if j > 0 && dp[i][j] == dp[i][j-1]+1 {
			ops = append(ops, EditOp{
				Kind: Insert,
				To:   br[j-1],
			})
			j--
			continue
		}

		if i > 0 && dp[i][j] == dp[i-1][j]+1 {
			ops = append(ops, EditOp{
				Kind: Delete,
				From: ar[i-1],
			})
			i--
			continue
		}

		// This should be unreachable if dp was built correctly.
		panic("editdistance: invalid backtrack state")
	}

	// Backtracking builds the script from right to left.
	reverseOps(ops)

	return dp[n][m], ops
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func reverseOps(ops []EditOp) {
	for left, right := 0, len(ops)-1; left < right; left, right = left+1, right-1 {
		ops[left], ops[right] = ops[right], ops[left]
	}
}
