import kotlinx.coroutines.*
import kotlinx.coroutines.Dispatchers.Default
import java.util.concurrent.atomic.AtomicLong

suspend fun parallelPrefixSum(
    input: LongArray,
    parallelism: Int = Runtime.getRuntime().availableProcessors()
): LongArray {
    require(parallelism > 0) { "parallelism must be positive" }
    val n = input.size
    if (n == 0) return LongArray(0)
    if (n == 1) return input.copyOf()

    // For small arrays, sequential is faster than the overhead
    if (n < 4096 || parallelism == 1) {
        return sequentialPrefixSum(input)
    }

    val p = minOf(parallelism, n)
    val chunkSize = (n + p - 1) / p

    // Step 1: Compute local inclusive prefix sums per chunk, in parallel
    // We work on a copy to avoid mutating caller's array
    val result = input.copyOf()
    val chunkTotals = LongArray(p)

    coroutineScope {
        val jobs = (0 until p).map { chunkIdx ->
            launch(Default) {
                val start = chunkIdx * chunkSize
                val end = minOf(start + chunkSize, n)
                var acc = 0L
                for (i in start until end) {
                    acc += input[i]
                    result[i] = acc
                }
                chunkTotals[chunkIdx] = acc
            }
        }
        jobs.forEach { it.join() }
    }

    // Step 2: Compute exclusive prefix sum of chunk totals
    // Sequential since p is small (number of cores)
    val chunkOffsets = LongArray(p)
    var running = 0L
    for (i in 0 until p) {
        chunkOffsets[i] = running
        running += chunkTotals[i]
    }

    // Step 3: Add offsets to each chunk in parallel
    coroutineScope {
        val jobs = (0 until p).map { chunkIdx ->
            launch(Default) {
                val offset = chunkOffsets[chunkIdx]
                if (offset == 0L) return@launch // skip chunk 0
                val start = chunkIdx * chunkSize
                val end = minOf(start + chunkSize, n)
                for (i in start until end) {
                    result[i] += offset
                }
            }
        }
        jobs.forEach { it.join() }
    }

    return result
}

