```rust
/// Returns the longest common subsequence (LCS) of two UTF-8 strings.
///
/// The result is a new `String`. Comparison is performed on Unicode scalar
/// values (`char`), not on bytes. For ASCII inputs this is equivalent to the
/// usual byte-oriented LCS, but for non-ASCII input it avoids splitting
/// multi-byte UTF-8 sequences.
///
/// This implementation uses Hirschberg's algorithm:
///
/// * Time:  O(n * m)
/// * Space: O(min(n, m)) auxiliary memory, excluding the returned string
///
/// The simple dynamic-programming solution stores an `n * m` table. That is
/// often unacceptable in a service where inputs can be large. Hirschberg's
/// algorithm keeps only one row of DP state at a time and reconstructs the LCS
/// by divide and conquer.
///
/// Tie-breaking is deterministic but arbitrary: if multiple LCS values exist,
/// this function returns one of them. If you need a specific one, you must
/// define the tie-breaking rule explicitly.
pub fn longest_common_subsequence(left: &str, right: &str) -> String {
    let left_chars: Vec<char> = left.chars().collect();
    let right_chars: Vec<char> = right.chars().collect();

    lcs_chars(&left_chars, &right_chars).into_iter().collect()
}

fn lcs_chars(a: &[char], b: &[char]) -> Vec<char> {
    if a.is_empty() || b.is_empty() {
        return Vec::new();
    }

    // Split the longer side to keep the DP row length as small as possible.
    // LCS is symmetric, so swapping the arguments is safe.
    if a.len() < b.len() {
        return lcs_chars(b, a);
    }

    // Base case: if `a` has one character, the best LCS is either that
    // character or empty. We still need to search all of `b`.
    if a.len() == 1 {
        return if b.contains(&a[0]) {
            vec![a[0]]
        } else {
            Vec::new()
        };
    }

    let mid = a.len() / 2;
    let (a_left, a_right) = a.split_at(mid);

    // `left_lens[j]` = LCS length of `a_left` and `b[..j]`.
    //
    // `right_lens[j]` = LCS length of `a_right` and `b[j..]`.
    //
    // We choose a split point `j` maximizing:
    //
    //     left_lens[j] + right_lens[j]
    //
    // This is the key Hirschberg step. It lets us find the optimal split in
    // `b` using only O(|b|) memory, then solve the two halves recursively.
    let split_b = {
        let left_lens = lcs_lengths_prefix(a_left, b);
        let right_lens = lcs_lengths_suffix(a_right, b);

        let mut best_j = 0;
        let mut best_len = 0;

        for j in 0..=b.len() {
            let len = left_lens[j] + right_lens[j];
            if len > best_len {
                best_len = len;
                best_j = j;
            }
        }

        best_j
    };

    // Important: the temporary DP vectors above are dropped before recursion,
    // so recursive calls do not retain O(|b|) memory per stack frame.
    let mut left = lcs_chars(a_left, &b[..split_b]);
    let right = lcs_chars(a_right, &b[split_b..]);

    left.extend(right);
    left
}

/// Returns `dp` where `dp[j]` is the LCS length of `a` and `b[..j]`.
fn lcs_lengths_prefix(a: &[char], b: &[char]) -> Vec<usize> {
    let mut dp = vec![0; b.len() + 1];

    for &ca in a {
        // `prev_diag` is the previous row's value at `j - 1`.
        let mut prev_diag = 0;

        for j in 1..=b.len() {
            let old = dp[j];

            if ca == b[j - 1] {
                dp[j] = prev_diag + 1;
            } else {
                dp[j] = old.max(dp[j - 1]);
            }

            prev_diag = old;
        }
    }

    dp
}

/// Returns `dp` where `dp[j]` is the LCS length of `a` and `b[j..]`.
fn lcs_lengths_suffix(a: &[char], b: &[char]) -> Vec<usize> {
    let n = b.len();
    let mut dp = vec![0; n + 1];

    for &ca in a.iter().rev() {
        // `next_diag` is the previous row's value at `j + 1`.
        let mut next_diag = 0;

        for j in (0..n).rev() {
            let old = dp[j];

            if ca == b[j] {
                dp[j] = next_diag + 1;
            } else {
                dp[j] = old.max(dp[j + 1]);
            }

            next_diag = old;
        }
    }

    dp
}
```

