#include <cuda_runtime.h>
#include <cstdint>

__device__ __forceinline__ uint32_t xorshift32(uint32_t& s) {
    s ^= s << 13;
    s ^= s >> 17;
    s ^= s << 5;
    return s;
}

// Minimal device-side exponential backoff + jitter retry wrapper.
// op() should return true on success, false to retry.
template <typename Op>
__device__ __forceinline__ bool retry_backoff_jitter(
    Op op,
    int max_attempts = 8,
    unsigned base_ns = 32,
    unsigned cap_ns = 2048)
{
    uint32_t seed = (blockIdx.x * 1664525u) ^
                    (threadIdx.x * 1013904223u) ^
                    static_cast<uint32_t>(clock64());
    if (seed == 0) seed = 1;

    for (int attempt = 0; attempt < max_attempts; ++attempt) {
        if (op()) return true;

        unsigned shift = attempt < 16 ? attempt : 16;
        unsigned backoff = base_ns << shift;
        if (backoff > cap_ns) backoff = cap_ns;

        unsigned jitter = xorshift32(seed) % (backoff + 1u);
        unsigned delay_ns = backoff + jitter;

#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 700
        __nanosleep(delay_ns);
#else
        unsigned long long t0 = clock64();
        while (clock64() - t0 < delay_ns) { }
#endif
    }
    return false;
}

// Example usage: retry a lock acquisition.
__global__ void example_kernel(int* lock) {
    bool got = retry_backoff_jitter([&] {
        return atomicCAS(lock, 0, 1) == 0;
    });

    if (got) {
        // critical section
        atomicExch(lock, 0);
    }
}
