# TypeScript Trie with Prefix Count

```typescript
class TrieNode {
  children: Map<string, TrieNode> = new Map();
  /** Number of times a word ends at this node */
  wordCount: number = 0;
  /** Number of words in the subtree rooted at this node (including this node) */
  prefixCount: number = 0;
}

export class Trie {
  private root: TrieNode = new TrieNode();

  /** Insert a word into the trie */
  insert(word: string): void {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch)!;
      node.prefixCount++;
    }
    node.wordCount++;
  }

  /** Returns true if the exact word exists in the trie */
  search(word: string): boolean {
    const node = this.traverse(word);
    return node !== null && node.wordCount > 0;
  }

  /** Returns the number of inserted words that start with the given prefix */
  prefixCount(prefix: string): number {
    const node = this.traverse(prefix);
    return node ? node.prefixCount : 0;
  }

  /** Returns the number of times an exact word was inserted */
  countExact(word: string): number {
    const node = this.traverse(word);
    return node ? node.wordCount : 0;
  }

  private traverse(word: string): TrieNode | null {
    let node = this.root;
    for (const ch of word) {
      const next = node.children.get(ch);
      if (!next) return null;
      node = next;
    }
    return node;
  }
}
```

## Usage Example

```typescript
const trie = new Trie();

trie.insert("apple");
trie.insert("app");
trie.insert("app");      // duplicates are allowed
trie.insert("apricot");
trie.insert("banana");

console.log(trie.search("app"));       // true
console.log(trie.search("ap"));        // false (not a complete word)
console.log(trie.search("apples"));    // false

console.log(trie.prefixCount("app"));  // 3  (apple, app, app)
console.log(trie.prefixCount("apr"));  // 1  (apricot)
console.log(trie.prefixCount("b"));    // 1  (banana)
console.log(trie.prefixCount("xyz"));  // 0

console.log(trie.countExact("app"));   // 2
console.log(trie.countExact("apple")); // 1
```

## How it works

- **`wordCount`** at a node counts how many times a word *ends* there, so duplicates are supported and `search` is exact.
- **`prefixCount`** at a node is incremented along the path during `insert`, giving **O(L)** prefix queries (where `L` is the prefix length) instead of walking the entire subtree.
- **Space complexity**: O(total characters inserted). **Insert / search / prefix count**: O(L).

# Topological Sort in C (with Cycle Detection)

Here's a complete implementation using **Kahn's algorithm** (BFS-based). It naturally detects cycles: if the process finishes without consuming all vertices, a cycle exists.

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

typedef struct {
    int n;              // number of vertices
    Edge **adj;         // adjacency list
    int *indegree;      // in-degree of each vertex
} Graph;

Graph *graph_create(int n) {
    Graph *g = malloc(sizeof(Graph));
    g->n = n;
    g->adj = calloc(n, sizeof(Edge *));
    g->indegree = calloc(n, sizeof(int));
    return g;
}

void graph_add_edge(Graph *g, int u, int v) {
    Edge *e = malloc(sizeof(Edge));
    e->to = v;
    e->next = g->adj[u];
    g->adj[u] = e;
    g->indegree[v]++;
}

void graph_free(Graph *g) {
    for (int i = 0; i < g->n; i++) {
        Edge *e = g->adj[i];
        while (e) { Edge *n = e->next; free(e); e = n; }
    }
    free(g->adj);
    free(g->indegree);
    free(g);
}

/*
 * Topological sort (Kahn's algorithm).
 *
 * On success: returns a malloc'd array of n vertices in topo order.
 * On cycle:   returns NULL (there is at least one cycle in the graph).
 */
int *topo_sort(Graph *g) {
    int n = g->n;
    int *order = malloc(sizeof(int) * n);
    int *queue = malloc(sizeof(int) * n);
    int head = 0, tail = 0, count = 0;

    // Enqueue all vertices with in-degree 0
    for (int v = 0; v < n; v++)
        if (g->indegree[v] == 0)
            queue[tail++] = v;

    while (head < tail) {
        int u = queue[head++];
        order[count++] = u;
        for (Edge *e = g->adj[u]; e; e = e->next) {
            if (--g->indegree[e->to] == 0)
                queue[tail++] = e->to;
        }
    }

    free(queue);

    if (count != n) {
        // Not all vertices were emitted => a cycle exists.
        free(order);
        return NULL;
    }
    return order;
}

/* Demo */
int main(void) {
    // Acyclic example: 5 -> 2 -> 3, 5 -> 0, 4 -> 0, 4 -> 1, 2 -> 3, 3 -> 1
    Graph *g = graph_create(6);
    graph_add_edge(g, 5, 2);
    graph_add_edge(g, 5, 0);
    graph_add_edge(g, 4, 0);
    graph_add_edge(g, 4, 1);
    graph_add_edge(g, 2, 3);
    graph_add_edge(g, 3, 1);

    int *order = topo_sort(g);
    if (!order) {
        printf("Cycle detected!\n");
    } else {
        printf("Topological order: ");
        for (int i = 0; i < g->n; i++) printf("%d ", order[i]);
        printf("\n");
        free(order);
    }
    graph_free(g);

    // Cyclic example: 0 -> 1 -> 2 -> 0
    Graph *c = graph_create(3);
    graph_add_edge(c, 0, 1);
    graph_add_edge(c, 1, 2);
    graph_add_edge(c, 2, 0);
    order = topo_sort(c);
    if (!order) printf("Cycle detected!\n");
    else { free(order); }
    graph_free(c);

    return 0;
}
```

### How the cycle check works

Kahn's algorithm repeatedly removes a vertex with in-degree zero. If the graph is a DAG, every vertex is eventually removed. If there's a cycle, **every vertex inside the cycle retains a positive in-degree forever** (each has an incoming edge from another member of the cycle), so its indegree can never reach zero — the queue drains with `count < n`. This test is exact.

### Optional: explicit cycle path reconstruction

If you want to *show* a cycle, you can run a DFS with colors (WHITE/GRAY/BLACK) and report a back edge. Kahn's algorithm tells you **whether** a cycle exists but not which one; DFS is more convenient for that.

---

## Complexity

Let **V = |V|** (vertices) and **E = |E|** (edges).

### Time: **O(V + E)**

- Initialization: one pass over vertices to fill the queue → **O(V)**.
- Each vertex is enqueued and dequeued exactly once → **O(V)**.
- Each edge is scanned exactly once (when its source is dequeued), decrementing the target's in-degree → **O(E)**.
- The final `count != n` check is O(1).

Total: **Θ(V + E)** — optimal, since any algorithm must look at every vertex and every edge at least once.

### Space: **O(V + E)**

- Adjacency list storage: **O(V + E)** (V head pointers + E nodes).
- `indegree` array: **O(V)**.
- `queue` array: at most V entries → **O(V)**.
- `order` output array: **O(V)**.

Ignoring the graph itself (which is input), the **extra working memory is O(V)**. If you count the graph representation, total space is **O(V + E)**.

---

### Comparison with DFS-based topological sort

- DFS-based sort (post-order reversal) is also **O(V + E)** time and **O(V)** extra space (recursion stack + colors).
- **Kahn's** is iterative (no stack overflow on deep graphs) and yields a *lexicographically smallest* topo order if you swap the queue for a min-heap (at O((V+E) log V) time).
- **DFS** is better if you need to *identify* the actual cycle vertices; Kahn's is better for streaming/incremental topo sort.

# LRU Cache in Swift

## Approach

An LRU cache needs three operations, all in **O(1)**:
- `get(key)` → return value and mark as recently used
- `put(key, value)` → insert or update; evict least-recently-used if over capacity
- Evict LRU when over capacity

We combine two data structures:
1. **Hash map** (`key → node`) for O(1) lookup
2. **Doubly linked list** for O(1) move-to-front and remove-from-back

We put the **most recently used** item at the front (head) and the **least recently used** at the back (tail). A sentinel head/tail avoids edge-case null checks.

## Implementation

```swift
final class LRUCache<Key: Hashable, Value> {

    private final class Node {
        let key: Key
        var value: Value
        var prev: Node?
        var next: Node?

        init(key: Key, value: Value) {
            self.key = key
            self.value = value
        }
    }

    private let capacity: Int
    private var map: [Key: Node] = [:]

    // Sentinels
    private let head = Node(key: 0 as! Key, value: 0 as! Value)
    // ^ avoid this trick in production; use optional sentinels instead (see below)

    private let tail = Node(key: 0 as! Key, value: 0 as! Value)

    init(capacity: Int) {
        precondition(capacity > 0, "Capacity must be > 0")
        self.capacity = capacity
        head.next = tail
        tail.prev = head
    }

    func get(_ key: Key) -> Value? {
        guard let node = map[key] else { return nil }
        moveToFront(node)
        return node.value
    }

    func put(_ key: Key, _ value: Value) {
        if let node = map[key] {
            node.value = value
            moveToFront(node)
            return
        }

        if map.count == capacity {
            // Evict LRU (node just before tail)
            if let lru = tail.prev, lru !== head {
                remove(lru)
                map.removeValue(forKey: lru.key)
            }
        }

        let node = Node(key: key, value: value)
        map[key] = node
        insertAtFront(node)
    }

    // MARK: - Linked list helpers

    private func insertAtFront(_ node: Node) {
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }

    private func remove(_ node: Node) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
        node.prev = nil
        node.next = nil
    }

    private func moveToFront(_ node: Node) {
        remove(node)
        insertAtFront(node)
    }
}
```

### Cleaner sentinel approach

The `as!` casts above are ugly. A better pattern uses dummy nodes with optional keys, or — since Swift doesn't have easy "dummy" values for arbitrary generics — use a wrapper around `Node?`:

```swift
final class LRUCache<Key: Hashable, Value> {

    private final class Node {
        let key: Key?
        var value: Value?
        var prev: Node?
        var next: Node?
        init(key: Key? = nil, value: Value? = nil) {
            self.key = key
            self.value = value
        }
    }

    private let capacity: Int
    private var map: [Key: Node] = [:]
    private let head = Node()   // dummy head
    private let tail = Node()   // dummy tail

    init(capacity: Int) {
        precondition(capacity > 0)
        self.capacity = capacity
        head.next = tail
        tail.prev = head
    }

    func get(_ key: Key) -> Value? {
        guard let node = map[key] else { return nil }
        moveToFront(node)
        return node.value
    }

    func put(_ key: Key, _ value: Value) {
        if let node = map[key] {
            node.value = value
            moveToFront(node)
            return
        }
        if map.count == capacity, let lru = tail.prev, lru !== head,
           let lruKey = lru.key {
            remove(lru)
            map.removeValue(forKey: lruKey)
        }
        let node = Node(key: key, value: value)
        map[key] = node
        insertAtFront(node)
    }

    private func insertAtFront(_ node: Node) {
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }

    private func remove(_ node: Node) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
    }

    private func moveToFront(_ node: Node) {
        remove(node)
        insertAtFront(node)
    }
}
```

## Usage

```swift
let cache = LRUCache<String, Int>(capacity: 2)
cache.put("a", 1)
cache.put("b", 2)
print(cache.get("a"))   // Optional(1)  → "a" is now most-recently used
cache.put("c", 3)       // evicts "b" (LRU)
print(cache.get("b"))   // nil
print(cache.get("c"))   // Optional(3)
```

## Complexity

Let **n = capacity**, **k = number of distinct keys currently stored** (≤ n).

### Time — `get`: **O(1)**
- Dictionary lookup: O(1) amortized
- `moveToFront`: unlink + relink a node in a doubly linked list, constant pointer updates
- Total: O(1)

### Time — `put`: **O(1)**
- Dictionary lookup for existing key: O(1)
- Insert new node at front: O(1)
- Eviction (remove tail node + dictionary removal): O(1)
- Total: O(1)

Both operations are truly constant-time, independent of capacity — the reason a doubly linked list (not array) is required.

### Space — **O(n)**
- Dictionary stores at most `n` entries: O(n)
- Linked list stores at most `n` nodes (plus 2 sentinels): O(n)
- Each node holds a `key`, a `value`, and two pointers
- Total: **O(n)**, where `n` is capacity

Note that each entry's `key` is stored **twice** — once in the dictionary and once in its node. That duplication is what enables O(1) eviction (when we remove the tail node, we know which dictionary key to delete).

## Why both structures?

| Operation | Array | Hash map alone | Hash map + DLL |
|---|---|---|---|
| Lookup | O(n) | O(1) ✅ | O(1) ✅ |
| Move to front | O(n) | — | O(1) ✅ |
| Evict LRU | O(n) | O(n) to find | O(1) ✅ |

A hash map alone can't track recency ordering; a linked list alone can't do O(1) lookup. Together they deliver O(1) on every operation — the classic LRU-cache invariant.

```ts
// csv.ts

export function parseCsv(input: string): string[][] {
  const rows: string[][] = [];

  let row: string[] = [];
  let field = "";

  let inQuotes = false;
  let justClosedQuote = false;
  let fieldStart = true;

  let i = 0;

  const pushField = () => {
    row.push(field);
    field = "";
    fieldStart = true;
  };

  const pushRow = () => {
    pushField();
    rows.push(row);
    row = [];
  };

  while (i < input.length) {
    const ch = input[i];

    if (inQuotes) {
      if (ch === '"') {
        // Escaped quote: ""
        if (input[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }

        // End of quoted field
        inQuotes = false;
        justClosedQuote = true;
        i++;
        continue;
      }

      // Commas, newlines, CR, and quotes are all literal inside quotes
      field += ch;
      i++;
      continue;
    }

    if (justClosedQuote) {
      if (ch === ",") {
        pushField();
        justClosedQuote = false;
        i++;
        continue;
      }

      if (ch === "\r" || ch === "\n") {
        pushRow();
        justClosedQuote = false;

        if (ch === "\r" && input[i + 1] === "\n") {
          i += 2;
        } else {
          i++;
        }

        continue;
      }

      throw new Error(
        `Invalid character ${JSON.stringify(ch)} after closing quote at position ${i}`
      );
    }

    if (ch === '"') {
      if (fieldStart) {
        inQuotes = true;
        fieldStart = false;
        i++;
        continue;
      }

      throw new Error(`Unexpected quote in unquoted field at position ${i}`);
    }

    if (ch === ",") {
      pushField();
      i++;
      continue;
    }

    if (ch === "\r" || ch === "\n") {
      pushRow();

      if (ch === "\r" && input[i + 1] === "\n") {
        i += 2;
      } else {
        i++;
      }

      continue;
    }

    field += ch;
    fieldStart = false;
    i++;
  }

  if (inQuotes) {
    throw new Error("Unterminated quoted field");
  }

  // Finalize the last row unless the input already ended with a record separator
  // and there is no additional pending data.
  if (
    !fieldStart ||
    field !== "" ||
    row.length > 0 ||
    (rows.length === 0 && input.length > 0)
  ) {
    pushRow();
  }

  return rows;
}
```

```ts
// csv.test.ts
import { describe, expect, it } from "vitest";
import { parseCsv } from "./csv";

describe("parseCsv", () => {
  it("returns an empty array for empty input", () => {
    expect(parseCsv("")).toEqual([]);
  });

  it("parses simple rows", () => {
    expect(parseCsv("a,b\nc,d")).toEqual([
      ["a", "b"],
      ["c", "d"],
    ]);
  });

  it("parses empty fields", () => {
    expect(parseCsv("a,,c")).toEqual([["a", "", "c"]]);
    expect(parseCsv(",,")).toEqual([["", "", ""]]);
    expect(parseCsv("a,")).toEqual([["a", ""]]);
  });

  it("parses quoted empty fields", () => {
    expect(parseCsv('""')).toEqual([[""]]);
    expect(parseCsv('"",x')).toEqual([["", "x"]]);
  });

  it("parses quoted fields with embedded commas", () => {
    expect(parseCsv('"a,b",c')).toEqual([["a,b", "c"]]);
  });

  it("parses escaped double quotes", () => {
    expect(parseCsv('"a""b"')).toEqual([['a"b']]);
  });

  it("parses escaped quotes and embedded commas together", () => {
    expect(parseCsv('"He said ""Hi, there"""')).toEqual([
      ['He said "Hi, there"'],
    ]);
  });

  it("parses quoted fields with embedded newlines", () => {
    expect(parseCsv('"line1\nline2",x')).toEqual([["line1\nline2", "x"]]);
  });

  it("parses quoted fields with embedded CRLF", () => {
    expect(parseCsv('"line1\r\nline2",x')).toEqual([
      ["line1\r\nline2", "x"],
    ]);
  });

  it("parses CRLF record separators", () => {
    expect(parseCsv("a,b\r\nc,d")).toEqual([
      ["a", "b"],
      ["c", "d"],
    ]);
  });

  it("does not add an extra empty row after a trailing newline", () => {
    expect(parseCsv("a,b\n")).toEqual([["a", "b"]]);
    expect(parseCsv('"a"\n')).toEqual([["a"]]);
  });

  it("parses blank lines as rows containing one empty field", () => {
    expect(parseCsv("a\n\nb")).toEqual([["a"], [""], ["b"]]);
  });

  it("throws on an unterminated quoted field", () => {
    expect(() => parseCsv('"a,b')).toThrow("Unterminated quoted field");
  });

  it("throws on an unexpected quote inside an unquoted field", () => {
    expect(() => parseCsv('a"b')).toThrow(
      "Unexpected quote in unquoted field"
    );
  });

  it("throws when characters appear after a closing quote", () => {
    expect(() => parseCsv('"a"b')).toThrow(
      "Invalid character"
    );
  });

  it("parses a mixed realistic example", () => {
    const csv = [
      'name,notes,active',
      'Alice,"Likes cats, dogs",true',
      'Bob,"Said ""hello""",false',
      'Carol,"line 1\nline 2",true',
    ].join("\r\n");

    expect(parseCsv(csv)).toEqual([
      ["name", "notes", "active"],
      ["Alice", "Likes cats, dogs", "true"],
      ["Bob", 'Said "hello"', "false"],
      ["Carol", "line 1\nline 2", "true"],
    ]);
  });
});
```

Key behaviors:

- Supports `,` as delimiter.
- Supports `"`-quoted fields.
- Handles `""` as an escaped quote inside quoted fields.
- Allows embedded commas, `\n`, `\r`, and `\r\n` inside quoted fields.
- Treats `\n`, `\r\n`, and `\r` as record separators outside quotes.
- Does not emit an extra empty row after a trailing record separator.
- Throws on malformed CSV such as unterminated quotes or characters after a closing quote.

