import random
import time
import functools
from typing import Callable, Type, Tuple, Union, TypeVar, Any

T = TypeVar("T")
ExceptionTypes = Union[Type[BaseException], Tuple[Type[BaseException], ...]]

def retry_with_backoff(
    max_retries: int = 5,
    base_delay: float = 0.1,
    max_delay: float = 10.0,
    exponential_base: float = 2.0,
    jitter: str = "full",  # "full", "equal", "none"? maybe
    retry_on: ExceptionTypes = Exception,
):
    if max_retries < 0: raise ValueError
    if base_delay < 0 etc.
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> T:
            last_exc = None
            for attempt in range(max_retries + 1): # total attempts
                try:
                    return func(*args, **kwargs)
                except retry_on as exc:
                    last_exc = exc
                    if attempt == max_retries:
                        raise
                    # compute delay
                    exp_delay = min(max_delay, base_delay * (exponential_base ** attempt))
                    if jitter == "full":
                        delay = random.uniform(0, exp_delay)
                    elif jitter == "equal":
                        delay = exp_delay / 2 + random.uniform(0, exp_delay / 2)
                    elif jitter == "none":
                        delay = exp_delay
                    else:
                        raise ValueError
                    time.sleep(delay)
            raise last_exc  # unreachable? 
        return wrapper
    return decorator

