enum { TOPO_CYCLE = 0, TOPO_OK = 1, TOPO_NOMEM = -1 };

/* Returns:
 *   TOPO_OK    if order[0..n-1] is a topological order
 *   TOPO_CYCLE if the graph has a cycle
 *   TOPO_NOMEM on allocation failure or invalid input
 */
int topo_sort(int n, const int *from, const int *to, int m, int *order)
{
    if (n < 0 || m < 0) return TOPO_NOMEM;
    if (n == 0) return TOPO_OK;

    if ((size_t)n > SIZE_MAX / (size_t)n) return TOPO_NOMEM;

    size_t nn = (size_t)n * (size_t)n;
    int *adj   = calloc(nn, sizeof *adj);
    int *indeg = calloc((size_t)n, sizeof *indeg);
    int *q     = malloc((size_t)n * sizeof *q);

    if (!adj || !indeg || !q) {
        free(adj);
        free(indeg);
        free(q);
        return TOPO_NOMEM;
    }

