class TokenBucket(
    private val capacity: Double,
    private val refillPerSecond: Double,
    private val clock: () -> Long = { System.nanoTime() }
) {
    private var tokens = capacity
    private var lastNanos = clock()

    @Synchronized
    fun tryAcquire(permits: Double = 1.0): Boolean {
        require(permits > 0.0 && permits <= capacity)

        val now = clock()
        val elapsedSeconds =
            (now - lastNanos).coerceAtLeast(0L) / 1_000_000_000.0

        tokens = minOf(capacity, tokens + elapsedSeconds * refillPerSecond)
        lastNanos = now

        return if (tokens >= permits) {
            tokens -= permits
            true
        } else {
            false
        }
    }
}
