```go
package main

import (
	"fmt"
	"math/rand"
	"time"
)

const (
	maxLevel    = 32
	probability = 0.25
)

type node struct {
	key  int
	next []*node
}

type SkipList struct {
	head  *node
	level int
	rng   *rand.Rand
}

func NewSkipList() *SkipList {
	return &SkipList{
		head:  &node{next: make([]*node, maxLevel)},
		level: 1,
		rng:   rand.New(rand.NewSource(time.Now().UnixNano())),
	}
}

func (s *SkipList) randomLevel() int {
	lvl := 1
	for lvl < maxLevel && s.rng.Float64() < probability {
		lvl++
	}
	return lvl
}

// Insert adds key to the skiplist. Duplicate keys are ignored.
func (s *SkipList) Insert(key int) {
	update := make([]*node, maxLevel)
	x := s.head

	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}

	x = x.next[0]
	if x != nil && x.key == key {
		return
	}

	lvl := s.randomLevel()
	if lvl > s.level {
		for i := s.level; i < lvl; i++ {
			update[i] = s.head
		}
		s.level = lvl
	}

	n := &node{
		key:  key,
		next: make([]*node, lvl),
	}

	for i := 0; i < lvl; i++ {
		n.next[i] = update[i].next[i]
		update[i].next[i] = n
	}
}

// Search reports whether key exists in the skiplist.
func (s *SkipList) Search(key int) bool {
	x := s.head

	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
	}

	x = x.next[0]
	return x != nil && x.key == key
}

// Delete removes key from the skiplist and reports whether it was found.
func (s *SkipList) Delete(key int) bool {
	update := make([]*node, maxLevel)
	x := s.head

	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}

	x = x.next[0]
	if x == nil || x.key != key {
		return false
	}

	for i := 0; i < s.level; i++ {
		if update[i].next[i] != x {
			break
		}
		update[i].next[i] = x.next[i]
	}

	for s.level > 1 && s.head.next[s.level-1] == nil {
		s.level--
	}

	return true
}

func main() {
	sl := NewSkipList()

	for _, v := range []int{3, 6, 7, 9, 12, 19, 17, 26, 21, 25} {
		sl.Insert(v)
	}

	fmt.Println("search 19:", sl.Search(19)) // true
	fmt.Println("search 20:", sl.Search(20)) // false

	fmt.Println("delete 19:", sl.Delete(19)) // true
	fmt.Println("search 19:", sl.Search(19)) // false
}
```

