final class SkipNode {
    let value: Int
    var next: [SkipNode?]

    init(_ value: Int, level: Int) {
        self.value = value
        self.next = Array(repeating: nil, count: level)
    }
}

final class SkipList {
    private let maxLevel: Int
    private let probability: Double
    private let header: SkipNode
    private var level: Int

    init(maxLevel: Int = 16, probability: Double = 0.5) {
        self.maxLevel = maxLevel
        self.probability = probability
        self.header = SkipNode(Int.min, level: maxLevel)
        self.level = 1
    }

    private func randomLevel() -> Int {
        var lvl = 1
        while Double.random(in: 0..<1) < probability && lvl < maxLevel {
            lvl += 1
        }
        return lvl
    }

    func search(_ target: Int) -> Bool {
        var x = header
        var i = level - 1

        while i >= 0 {
            while let nxt = x.next[i], nxt.value < target {
                x = nxt
            }
            i -= 1
        }

        guard let candidate = x.next[0] else { return false }
        return candidate.value == target
    }

    func insert(_ value: Int) {
        var update = Array(repeating: header, count: maxLevel)
        var x = header

        for i in stride(from: level - 1, through: 0, by: -1) {
            while let nxt = x.next[i], nxt.value < value {
                x = nxt
            }
            update[i] = x
        }

        // No duplicates in this minimal version.
        if let nxt = x.next[0], nxt.value == value {
            return
        }

        let newLevel = randomLevel()

        if newLevel > level {
            for i in level..<newLevel {
                update[i] = header
            }
            level = newLevel
        }

        let newNode = SkipNode(value, level: newLevel)

        for i in 0..<newLevel {
            newNode.next[i] = update[i].next[i]
            update[i].next[i] = newNode
        }
    }

    @discardableResult
    func delete(_ value: Int) -> Bool {
        var update = Array(repeating: header, count: maxLevel)
        var x = header

        for i in stride(from: level - 1, through: 0, by: -1) {
            while let nxt = x.next[i], nxt.value < value {
                x = nxt
            }
            update[i] = x
        }

        guard let target = x.next[0], target.value == value else {
            return false
        }

        for i in 0..<level {
            if update[i].next[i] === target {
                update[i].next[i] = target.next[i]
            } else {
                break
            }
        }

        while level > 1 && header.next[level - 1] == nil {
            level -= 1
        }

        return true
    }
}
