# Edit Distance with Edit Script (C++)

Below is a complete implementation of the Levenshtein edit distance algorithm that also reconstructs the edit script (sequence of insertions, deletions, and substitutions).

```cpp
#include <algorithm>
#include <string>
#include <vector>
#include <iostream>
#include <cstddef>

enum class EditOp { Match, Substitute, Delete, Insert };

struct Edit {
    EditOp op;
    std::size_t a_pos;   // position in source (0-based); valid for Match/Substitute/Delete
    std::size_t b_pos;   // position in target (0-based); valid for Match/Substitute/Insert
    char a_char;         // character in source (or '\0')
    char b_char;         // character in target (or '\0')
};

struct EditResult {
    int distance;
    std::vector<Edit> script;
};

// Computes Levenshtein distance between `a` and `b` and reconstructs
// an edit script (a sequence of edits transforming `a` into `b`).
EditResult edit_distance(const std::string& a, const std::string& b) {
    const std::size_t n = a.size();
    const std::size_t m = b.size();

    // DP table: dp[i][j] = edit distance between a[0..i) and b[0..j)
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));
    for (std::size_t i = 0; i <= n; ++i) dp[i][0] = static_cast<int>(i);
    for (std::size_t j = 0; j <= m; ++j) dp[0][j] = static_cast<int>(j);

    for (std::size_t i = 1; i <= n; ++i) {
        for (std::size_t j = 1; j <= m; ++j) {
            int cost = (a[i - 1] == b[j - 1]) ? 0 : 1;
            dp[i][j] = std::min({
                dp[i - 1][j - 1] + cost, // substitute or match
                dp[i - 1][j] + 1,        // delete a[i-1]
                dp[i][j - 1] + 1         // insert b[j-1]
            });
        }
    }

    // Backtrack to produce an edit script.
    EditResult result;
    result.distance = dp[n][m];

    std::size_t i = n, j = m;
    while (i > 0 || j > 0) {
        if (i > 0 && j > 0) {
            int cost = (a[i - 1] == b[j - 1]) ? 0 : 1;
            if (dp[i][j] == dp[i - 1][j - 1] + cost) {
                result.script.push_back({
                    cost == 0 ? EditOp::Match : EditOp::Substitute,
                    i - 1, j - 1, a[i - 1], b[j - 1]
                });
                --i; --j;
                continue;
            }
        }
        if (i > 0 && dp[i][j] == dp[i - 1][j] + 1) {
            result.script.push_back({EditOp::Delete, i - 1, j, a[i - 1], '\0'});
            --i;
            continue;
        }
        // Must be an insertion
        result.script.push_back({EditOp::Insert, i, j - 1, '\0', b[j - 1]});
        --j;
    }

    std::reverse(result.script.begin(), result.script.end());
    return result;
}

// Utility: print an edit script in a human-readable form.
void print_script(const EditResult& res) {
    std::cout << "Edit distance = " << res.distance << "\n";
    for (const auto& e : res.script) {
        switch (e.op) {
            case EditOp::Match:
                std::cout << "  match      a[" << e.a_pos << "]='" << e.a_char
                          << "' == b[" << e.b_pos << "]='" << e.b_char << "'\n";
                break;
            case EditOp::Substitute:
                std::cout << "  substitute a[" << e.a_pos << "]='" << e.a_char
                          << "' -> b[" << e.b_pos << "]='" << e.b_char << "'\n";
                break;
            case EditOp::Delete:
                std::cout << "  delete     a[" << e.a_pos << "]='" << e.a_char << "'\n";
                break;
            case EditOp::Insert:
                std::cout << "  insert     b[" << e.b_pos << "]='" << e.b_char << "'\n";
                break;
        }
    }
}
