## Notes

- **Complexity**: O(n·m) time and O(n·m) memory. Memory can be reduced to O(min(n,m)) if only the distance is needed, but the full table is required to reconstruct the script.
- **Tie-breaking**: When multiple optimal paths exist, this implementation prefers `Match/Substitute`, then `Delete`, then `Insert` — a common convention that tends to keep aligned characters together.
- **Semantics of edits**: Each `Edit` record describes what happens at the current cursor position of the source and target strings. `Match` entries are included in the script so the alignment is fully explicit; strip them out if you only want the mutating operations.

```ts
// retry.ts

export type Sleep = (ms: number) => Promise<void>;

export interface RetryOptions {
  /** Number of retries after the initial attempt. Default: 3 */
  retries?: number;
  /** Initial delay in milliseconds. Default: 100 */
  baseDelayMs?: number;
  /** Maximum delay in milliseconds. Default: 10_000 */
  maxDelayMs?: number;
  /** Exponential factor. Default: 2 */
  factor?: number;
  /** Apply full jitter: random(0, cappedExponentialDelay). Default: true */
  jitter?: boolean;
  /** Return false to stop retrying immediately. Attempt is zero-based. */
  shouldRetry?: (error: unknown, attempt: number) => boolean;
  /** Called before sleeping between retries. */
  onRetry?: (error: unknown, attempt: number, delayMs: number) => void;
  /** Injectable random function for deterministic tests. Default: Math.random */
  random?: () => number;
  /** Injectable sleep function for deterministic tests. */
  sleep?: Sleep;
}

const defaultSleep: Sleep = (ms) =>
  new Promise<void>((resolve) => setTimeout(resolve, ms));

function assertNonNegativeFinite(name: string, value: number): void {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a non-negative finite number`);
  }
}

function computeDelay(
  attempt: number,
  baseDelayMs: number,
  maxDelayMs: number,
  factor: number,
  jitter: boolean,
  random: () => number,
): number {
  const exponentialDelay = Math.min(
    maxDelayMs,
    baseDelayMs * factor ** attempt,
  );

  if (!jitter) {
    return exponentialDelay;
  }

  // Full jitter: uniformly random between 0 and the capped exponential delay.
  const randomValue = Math.min(Math.max(random(), 0), 1);
  return Math.floor(randomValue * exponentialDelay);
}

export async function retry<T>(
  operation: (attempt: number) => Promise<T> | T,
  options: RetryOptions = {},
): Promise<T> {
  const {
    retries = 3,
    baseDelayMs = 100,
    maxDelayMs = 10_000,
    factor = 2,
    jitter = true,
    shouldRetry = () => true,
    onRetry,
    random = Math.random,
    sleep = defaultSleep,
  } = options;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError('retries must be a non-negative integer');
  }

  assertNonNegativeFinite('baseDelayMs', baseDelayMs);
  assertNonNegativeFinite('maxDelayMs', maxDelayMs);

  if (!Number.isFinite(factor) || factor < 1) {
    throw new RangeError('factor must be a finite number >= 1');
  }

  let lastError: unknown;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await operation(attempt);
    } catch (error) {
      lastError = error;

      const isLastAttempt = attempt === retries;
      if (isLastAttempt || !shouldRetry(error, attempt)) {
        throw error;
      }

      const delayMs = computeDelay(
        attempt,
        baseDelayMs,
        maxDelayMs,
        factor,
        jitter,
        random,
      );

      onRetry?.(error, attempt, delayMs);
      await sleep(delayMs);
    }
  }

  // TypeScript control-flow safety; the loop always returns or throws.
  throw lastError;
}
