PostgreSQL example (PL/pgSQL). It consumes a query one row at a time, so it does not need to know the stream length in advance.

```sql
CREATE OR REPLACE FUNCTION reservoir_sample(
    k int,
    query text
)
RETURNS TABLE (row_data jsonb)
LANGUAGE plpgsql
AS $$
DECLARE
    rec       record;
    i         bigint := 0;                -- number of items seen
    j         bigint;                     -- random index in 1..i
    reservoir jsonb[] := ARRAY[]::jsonb[]; -- holds up to k items
BEGIN
    IF k IS NULL OR k <= 0 THEN
        RETURN;
    END IF;

    -- Iterate without counting the stream first.
    FOR rec IN EXECUTE format(
        'SELECT row_to_json(t)::jsonb AS r FROM (%s) t',
        query
    )
    LOOP
        i := i + 1;

        IF i <= k THEN
            -- Fill the reservoir.
            reservoir := reservoir || rec.r;
        ELSE
            -- Algorithm R: pick j uniformly from 1..i.
            j := floor(random() * i)::bigint + 1;

            IF j <= k THEN
                reservoir[j] := rec.r;
            END IF;
        END IF;
    END LOOP;

    RETURN QUERY SELECT unnest(reservoir);
END;
$$;
```

Usage example:

```sql
-- Pick a uniform random sample of 5 users without knowing the row count first.
SELECT
    row_data->>'id'   AS id,
    row_data->>'name' AS name
FROM reservoir_sample(
    5,
    'SELECT id, name FROM users'
);
```

If the stream has fewer than `k` rows, it returns all rows. For an already-materialized table where you do not need one-pass streaming, the simpler set-based version is:

```sql
SELECT *
FROM users
ORDER BY random()
LIMIT 5;
```

But the function above implements true reservoir sampling over a stream/query.

# Kotlin Trie with Unit Tests

Below is a complete implementation of a trie supporting `insert`, `exact search`, and `prefix count`, followed by unit tests covering edge cases.

## Implementation

```kotlin
package trie

/**
 * A trie (prefix tree) supporting insertion, exact-match search, and prefix counting.
 * Words are case-sensitive by default; pass a custom normalizer if needed.
 */
class Trie(
    private val normalizer: (Char) -> Char = { it }
) {
    private class Node {
        val children = HashMap<Char, Node>()
        var isTerminal = false
        var prefixCount = 0  // number of words that pass through this node (inclusive)
    }

    private val root = Node()
    var size: Int = 0
        private set

    /** Inserts [word] into the trie. Duplicate insertions are ignored. */
    fun insert(word: String) {
        require(word.isNotEmpty()) { "Cannot insert empty word" }
        var node = root
        for (c in word) {
            val key = normalizer(c)
            node = node.children.getOrPut(key) { Node() }
            node.prefixCount++
        }
        if (!node.isTerminal) {
            node.isTerminal = true
            size++
        }
    }

    /** Returns true if [word] was previously inserted. */
    fun contains(word: String): Boolean {
        if (word.isEmpty()) return false
        val node = findNode(word) ?: return false
        return node.isTerminal
    }

    /** Returns how many distinct inserted words start with [prefix]. */
    fun countWithPrefix(prefix: String): Int {
        if (prefix.isEmpty()) return size
        return findNode(prefix)?.prefixCount ?: 0
    }

    private fun findNode(word: String): Node? {
        var node = root
        for (c in word) {
            node = node.children[normalizer(c)] ?: return null
        }
        return node
    }
}
```

### Why the extra `prefixCount` field?

Each node stores how many inserted words pass through it. This makes `countWithPrefix` **O(L)** where L is the prefix length — no subtree traversal needed. The trade-off: `insert` and `delete` must touch every node on the path (which they already do anyway).

## Unit Tests

```kotlin
package trie

import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows

class TrieTest {

    private lateinit var trie: Trie

    @BeforeEach
    fun setUp() {
        trie = Trie()
    }

    // ---------- Basic insert / search ----------

    @Test
    fun `empty trie returns false and zero`() {
        assertFalse(trie.contains("a"))
        assertEquals(0, trie.countWithPrefix("a"))
        assertEquals(0, trie.countWithPrefix(""))
        assertEquals(0, trie.size)
    }

    @Test
    fun `insert and exact search`() {
        trie.insert("apple")
        assertTrue(trie.contains("apple"))
        assertFalse(trie.contains("appl"))
        assertFalse(trie.contains("apples"))
        assertEquals(1, trie.size)
    }

    @Test
    fun `inserting duplicate does not change size`() {
        trie.insert("cat")
        trie.insert("cat")
        trie.insert("cat")
        assertEquals(1, trie.size)
        assertTrue(trie.contains("cat"))
        assertEquals(1, trie.countWithPrefix("cat"))
    }

    // ---------- Prefix counting ----------

    @Test
    fun `prefix count on populated trie`() {
        listOf("car", "cart", "carbon", "cat", "dog").forEach(trie::insert)
        assertEquals(4, trie.countWithPrefix("ca"))
        assertEquals(3, trie.countWithPrefix("car"))
        assertEquals(1, trie.countWithPrefix("cart"))
        assertEquals(1, trie.countWithPrefix("carto"))
        assertEquals(0, trie.countWithPrefix("cartoon"))
        assertEquals(1, trie.countWithPrefix("d"))
        assertEquals(5, trie.countWithPrefix(""))
    }

    @Test
    fun `word that is a prefix of another is counted correctly`() {
        trie.insert("app")
        trie.insert("apple")
        assertEquals(2, trie.countWithPrefix("app"))
        assertEquals(1, trie.countWithPrefix("appl"))
        assertTrue(trie.contains("app"))
        assertTrue(trie.contains("apple"))
        assertFalse(trie.contains("appl"))
    }

    @Test
    fun `prefix not present returns zero`() {
        trie.insert("hello")
        assertEquals(0, trie.countWithPrefix("world"))
        assertEquals(0, trie.countWithPrefix("hellx"))
        assertEquals(0, trie.countWithPrefix("hellos"))
    }

    // ---------- Empty-string handling ----------

    @Test
    fun `empty string is not stored`() {
        trie.insert("")
        assertEquals(0, trie.size)
        assertFalse(trie.contains(""))
    }

    @Test
    fun `empty prefix returns total size`() {
        listOf("a", "b", "c").forEach(trie::insert)
        assertEquals(3, trie.countWithPrefix(""))
    }

    // ---------- Edge cases on insert ----------

    @Test
    fun `insert blank string throws`() {
        assertThrows<IllegalArgumentException> { trie.insert("") }
    }

    @Test
    fun `single character word`() {
        trie.insert("a")
        assertTrue(trie.contains("a"))
        assertEquals(1, trie.countWithPrefix("a"))
        assertEquals(1, trie.countWithPrefix(""))
        assertFalse(trie.contains("aa"))
    }

    @Test
    fun `words are case-sensitive by default`() {
        trie.insert("Apple")
        assertTrue(trie.contains("Apple"))
        assertFalse(trie.contains("apple"))
        assertEquals(0, trie.countWithPrefix("a"))
        assertEquals(1, trie.countWithPrefix("A"))
    }

    @Test
    fun `custom normalizer makes lookups case-insensitive`() {
        val ci = Trie(normalizer = Char::lowercaseChar)
        ci.insert("Hello")
        assertTrue(ci.contains("hello"))
        assertTrue(ci.contains("HELLO"))
        assertEquals(1, ci.countWithPrefix("HeL"))
    }

    @Test
    fun `unicode characters are supported`() {
        trie.insert("café")
        trie.insert("猫")
        trie.insert("🐱")
        assertTrue(trie.contains("café"))
        assertTrue(trie.contains("猫"))
        assertTrue(trie.contains("🐱"))
        assertEquals(1, trie.countWithPrefix("ca"))
        assertEquals(1, trie.countWithPrefix("🐱"))
    }

    @Test
    fun `long string is handled`() {
        val s = "a".repeat(10_000)
        trie.insert(s)
        assertTrue(trie.contains(s))
        assertEquals(1, trie.countWithPrefix("a".repeat(5_000)))
        assertEquals(0, trie.countWithPrefix(s + "b"))
    }

    // ---------- Structural edge cases ----------

    @Test
    fun `diamond in prefix paths`() {
        // "bat" and "bet" share 'b'; both must be counted under prefix "b"
        trie.insert("bat")
        trie.insert("bet")
        assertEquals(2, trie.countWithPrefix("b"))
        assertEquals(1, trie.countWithPrefix("ba"))
        assertEquals(1, trie.countWithPrefix("be"))
        assertTrue(trie.contains("bat"))
        assertTrue(trie.contains("bet"))
        assertFalse(trie.contains("bit"))
    }

    @Test
    fun `words that are prefixes of each other`() {
        trie.insert("a")
        trie.insert("ab")
        trie.insert("abc")
        trie.insert("abcd")
        assertEquals(4, trie.countWithPrefix("a"))
        assertEquals(3, trie.countWithPrefix("ab"))
        assertEquals(2, trie.countWithPrefix("abc"))
        assertEquals(1, trie.countWithPrefix("abcd"))
        assertEquals(0, trie.countWithPrefix("abcde"))
        assertTrue(trie.contains("a"))
        assertTrue(trie.contains("abcd"))
    }
}
```

## What the tests cover

| Category | Cases covered |
|---|---|
| **Empty trie** | `contains` → false, `countWithPrefix` → 0 |
| **Basic flows** | insert / contains / prefix count |
| **Duplicates** | inserting same word N times only counts once |
| **Prefix of word** | "app" counting when "apple" also present |
| **Word of prefix** | "car" is a stored word and a prefix of "cart" |
| **Empty string** | insert throws / contains false / prefix "" → size |
| **Case sensitivity** | default is case-sensitive; custom normalizer works |
| **Unicode** | accented letters, CJK, emoji |
| **Long strings** | 10 000-char word, no stack overflow (iterative) |
| **Diamond paths** | branching siblings counted correctly |
| **Chained prefixes** | a / ab / abc / abcd all correct |

## Complexity

- `insert(word)` — **O(L)** time, **O(L)** space (new nodes)
- `contains(word)` — **O(L)** time
- `countWithPrefix(prefix)` — **O(L)** time (thanks to stored `prefixCount`)
- Memory — **O(total characters across distinct words)**

```kotlin
sealed class Token {
    data class Number(val value: Double) : Token()
    data object Plus : Token()
    data object Minus : Token()
    data object Star : Token()
    data object Slash : Token()
    data object LParen : Token()
    data object RParen : Token()
    data object End : Token()
}

fun tokenize(expression: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0

    while (i < expression.length) {
        val c = expression[i]

        when {
            c.isWhitespace() -> {
                i++
            }

            c.isDigit() || c == '.' -> {
                val start = i
                var seenDot = false

                while (i < expression.length) {
                    val ch = expression[i]
                    if (ch.isDigit()) {
                        i++
                    } else if (ch == '.' && !seenDot) {
                        seenDot = true
                        i++
                    } else {
                        break
                    }
                }

                val text = expression.substring(start, i)
                val value = text.toDoubleOrNull()
                    ?: throw IllegalArgumentException("Invalid number: $text")
                tokens += Token.Number(value)
            }

            c == '+' -> {
                tokens += Token.Plus
                i++
            }

            c == '-' -> {
                tokens += Token.Minus
                i++
            }

            c == '*' -> {
                tokens += Token.Star
                i++
            }

            c == '/' -> {
                tokens += Token.Slash
                i++
            }

            c == '(' -> {
                tokens += Token.LParen
                i++
            }

            c == ')' -> {
                tokens += Token.RParen
                i++
            }

            else -> throw IllegalArgumentException(
                "Unexpected character '$c' at index $i"
            )
        }
    }

    tokens += Token.End
    return tokens
}

private class Parser(private val tokens: List<Token>) {
    private var position = 0

    fun parse(): Double {
        val result = expression()
        if (peek() !is Token.End) {
            throw IllegalArgumentException("Unexpected token: ${peek()}")
        }
        return result
    }

    private fun expression(): Double {
        var value = term()

        while (true) {
            value = when (peek()) {
                Token.Plus -> {
                    next()
                    value + term()
                }

                Token.Minus -> {
                    next()
                    value - term()
                }

                else -> return value
            }
        }
    }

    private fun term(): Double {
        var value = unary()

        while (true) {
            value = when (peek()) {
                Token.Star -> {
                    next()
                    value * unary()
                }

                Token.Slash -> {
                    next()
                    value / unary()
                }

                else -> return value
            }
        }
    }

    private fun unary(): Double {
        return when (peek()) {
            Token.Plus -> {
                next()
                unary()
            }

            Token.Minus -> {
                next()
                -unary()
            }

            else -> primary()
        }
    }

    private fun primary(): Double {
        return when (val token = next()) {
            is Token.Number -> token.value

            Token.LParen -> {
                val value = expression()
                val close = next()
                if (close != Token.RParen) {
                    throw IllegalArgumentException("Expected ')'")
                }
                value
            }

            else -> throw IllegalArgumentException("Unexpected token: $token")
        }
    }

    private fun peek(): Token = tokens[position]

    private fun next(): Token = tokens[position++]
}

fun evaluate(expression: String): Double {
    return Parser(tokenize(expression)).parse()
}

fun main() {
    println(evaluate("2 + 3 * (4 - 1)")) // 11.0
    println(evaluate("-(2 + 3) / 2"))    // -2.5
    println(evaluate("10 / 2 + 3 * 4"))  // 17.0
}
```

