# Exponential Backoff Retry with Jitter in Rust

Here's a complete implementation with comprehensive unit tests.

## `Cargo.toml`

```toml
[package]
name = "retry-backoff"
version = "0.1.0"
edition = "2021"

[dependencies]
rand = "0.8"

[dev-dependencies]
```

## `src/lib.rs`

```rust
use rand::Rng;
use std::future::Future;
use std::time::Duration;

/// Configuration for exponential backoff with jitter.
#[derive(Debug, Clone)]
pub struct RetryConfig {
    /// Maximum number of retry attempts (excluding the initial attempt).
    pub max_retries: u32,
    /// Initial delay before the first retry.
    pub initial_delay: Duration,
    /// Maximum delay cap between attempts.
    pub max_delay: Duration,
    /// Multiplier applied to the delay each retry (commonly 2.0).
    pub multiplier: f64,
    /// Fraction of the computed delay that is subject to jitter (0.0..=1.0).
    /// Uses "full jitter" scaled by this factor:
    /// `delay = base * (1 - jitter) + rand(0..=base * jitter)`
    pub jitter: f64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_retries: 5,
            initial_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(30),
            multiplier: 2.0,
            jitter: 1.0,
        }
    }
}

/// Compute the (non-jittered) base delay for attempt `n` (0-indexed).
pub fn base_delay(config: &RetryConfig, attempt: u32) -> Duration {
    if attempt == 0 {
        return config.initial_delay.min(config.max_delay);
    }
    let multiplier = config.multiplier.max(1.0);
    let base_ms = config.initial_delay.as_secs_f64()
        * multiplier.powi(attempt.min(63) as i32);
    let capped = base_ms.min(config.max_delay.as_secs_f64());
    Duration::from_secs_f64(capped)
}

/// Apply jitter to a base delay. `jitter` is clamped to `[0.0, 1.0]`.
/// Uses `rand::thread_rng` internally; the jittered delay is bounded by
/// `[base * (1 - jitter), base]`.
pub fn apply_jitter(base: Duration, jitter: f64) -> Duration {
    if jitter <= 0.0 {
        return base;
    }
    let jitter = jitter.min(1.0);
    let base_secs = base.as_secs_f64();
    let low = base_secs * (1.0 - jitter);
    let high = base_secs;
    let picked = if high > low {
        rand::thread_rng().gen_range(low..=high)
    } else {
        high
    };
    Duration::from_secs_f64(picked)
}

/// Compute the delay to wait after a failed attempt (0-indexed).
pub fn delay_for_attempt(config: &RetryConfig, attempt: u32) -> Duration {
    let base = base_delay(config, attempt);
    apply_jitter(base, config.jitter)
}

/// Errors surfaced by `retry`.
#[derive(Debug)]
pub enum RetryError<E> {
    /// All attempts exhausted. Contains the last error and the attempts made.
    Exhausted { last_error: E, attempts: u32 },
    /// The config refused to run (e.g. `max_retries == 0` when retries are required).
    InvalidConfig,
}

/// Retry an async operation with exponential backoff + jitter.
///
/// - `op` is the operation to run. It must be `FnMut(u32) -> Future` so it can
///   be invoked multiple times; the argument is the current attempt index (0-based).
/// - `should_retry` decides whether a given error is retryable.
///
/// The future returned by `op` must be `Send` for use with `tokio::spawn`.
pub async fn retry<F, Fut, T, E, P>(
    config: &RetryConfig,
    mut op: F,
    should_retry: P,
) -> Result<T, RetryError<E>>
where
    F: FnMut(u32) -> Fut,
    Fut: Future<Output = Result<T, E>>,
    P: Fn(&E) -> bool,
{
    // Reject non-sensical configs early so callers get a clear signal.
    if config.max_retries > 1_000 {
        return Err(RetryError::InvalidConfig);
    }

    let mut attempts: u32 = 0;
    loop {
        match op(attempts).await {
            Ok(v) => return Ok(v),
            Err(e) => {
                if attempts >= config.max_retries || !should_retry(&e) {
                    return Err(RetryError::Exhausted {
                        last_error: e,
                        attempts: attempts + 1,
                    });
                }
                let delay = delay_for_attempt(config, attempts);
                tokio_sleep(delay).await;
                attempts += 1;
            }
        }
    }
}

/// Small indirection so tests can run without a runtime; uses a plain async sleep.
/// In a real crate, use `tokio::time::sleep`.
async fn tokio_sleep(dur: Duration) {
    tokio::time::sleep(dur).await;
}

