//   - `order_` is a doubly-linked list of {key, value}. Front = most recently
//     used, back = least recently used.
//   - `index_` maps key -> iterator into `order_`.
//
// Why std::list (and not vector/deque):
//   We store iterators into `order_` in `index_`. std::list iterators remain
//   valid across insertions and erasures of *other* elements — vector/deque
//   iterators do not. This is what lets us do O(1) lookup + O(1) move.
//
// Why splice() and not erase+push_front:
//   std::list::splice relinks the existing node in O(1) without copying the
//   value and without invalidating the iterator stored in `index_`. If we did
//   erase+push_front we would have to (a) copy the value, and (b) update the
//   iterator in `index_` for that key. splice is both faster and simpler.

template <typename Key, typename Value, typename Hash = std::hash<Key>,
          typename Eq = std::equal_to<Key>>
class LRUCache {
public:
    using value_type = std::pair<const Key, Value>;
    using list_type = std::list<value_type>;

    explicit LRUCache(std::size_t capacity) : capacity_(capacity) {
        if (capacity_ == 0) {
            // Allow construction but all puts are no-ops / gets miss.
            // Alternative: throw std::invalid_argument. See put().
        }
    }

    // Returns the value and marks the key as most-recently-used.
    // Returns std::nullopt on miss.
    //
    // Note: get() is intentionally non-const — LRU recency is part of the
    // logical state. A const get() would either lie or require mutable members
    // plus external locking; the latter is what a thread-safe wrapper does.
    std::optional<Value> get(const Key& key) {
        auto it = index_.find(key);
        if (it == index_.end()) return std::nullopt;

        // Move node to the front (MRU). splice preserves the iterator in
        // index_, so no bookkeeping is needed here.
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    // Inserts or updates. Marks key as most-recently-used.
    void put(const Key& key, const Value& value) {
        if (capacity_ == 0) return;

        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }

        // Insert at front. emplace_back then splice would also work, but
        // emplace at begin is simplest. Note: we push the list node FIRST and
        // then insert into the map; if the map insert throws, we must clean up
        // the list node (see try/catch below) to keep the two in sync.
        order_.emplace_front(key, value);
        try {
            // try_emplace avoids constructing the iterator if the key already
            // exists; here we've already checked, but it also makes the
            // "insert only" intent explicit and avoids a redundant pair ctor.
            index_.emplace(order_.front().first, order_.begin());
        } catch (...) {
            order_.pop_front();
            throw;
        }

        if (order_.size() > capacity_) {
            // Evict LRU (back).
            index_.erase(order_.back().first);
            order_.pop_back();
        }
    }

    // Move overload — useful when values are expensive to copy.
    void put(Key&& key, Value&& value) {
        if (capacity_ == 0) return;

        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = std::move(value);
            order_.splice(order_.begin(), order_, it->second);
            return;
        }

        order_.emplace_front(std::move(key), std::move(value));
        try {
            index_.emplace(order_.front().first, order_.begin());
        } catch (...) {
            order_.pop_front();
            throw;
        }
        if (order_.size() > capacity_) {
            index_.erase(order_.back().first);
            order_.pop_back();
        }
    }

    bool contains(const Key& key) const {
        return index_.find(key) != index_.end();
    }

    std::size_t size() const noexcept { return index_.size(); }
    std::size_t capacity() const noexcept { return capacity_; }
    bool empty() const noexcept { return index_.empty(); }

    // Optional: clear() for shutdown / tests.
    void clear() noexcept {
        index_.clear();
        order_.clear();
    }

private:
    std::size_t capacity_;
    list_type order_;                                        // MRU at front
    std::unordered_map<Key, typename list_type::iterator, Hash, Eq> index_;
};

} // namespace cache
```

