data class Interval(val start: Int, val end: Int)

fun mergeIntervals(intervals: List<Interval>): List<Interval> {
    if (intervals.isEmpty()) return emptyList()

    val sorted = intervals.sortedWith(compareBy({ it.start }, { it.end }))
    val merged = mutableListOf<Interval>()

    var current = sorted.first()

    for (i in 1 until sorted.size) {
        val next = sorted[i]

        if (next.start <= current.end) {
            current = current.copy(end = maxOf(current.end, next.end))
        } else {
            merged.add(current)
            current = next
        }
    }

    merged.add(current)
    return merged
}

fun main() {
    val intervals = listOf(
        Interval(1, 3),
        Interval(2, 6),
        Interval(8, 10),
        Interval(15, 18)
    )

    println(mergeIntervals(intervals))
    // Output: [Interval(start=1, end=6), Interval(start=8, end=10), Interval(start=15, end=18)]
}
```

This treats intervals that touch, such as `[1, 3]` and `[3, 5]`, as overlapping. If you only want strictly overlapping intervals, change `next.start <= current.end` to `next.start < current.end`.

