# TypeScript Arithmetic Expression Tokenizer & Evaluator

Below is a complete implementation with a tokenizer, a recursive-descent parser/evaluator (which naturally handles operator precedence), and a comprehensive test suite.

## Implementation

```typescript
// arithmetic.ts

export type TokenType =
  | "NUMBER"
  | "PLUS"
  | "MINUS"
  | "STAR"
  | "SLASH"
  | "LPAREN"
  | "RPAREN";

export interface Token {
  type: TokenType;
  value: string;
  position: number;
}

export class TokenizeError extends Error {
  constructor(message: string, public position: number) {
    super(`${message} at position ${position}`);
    this.name = "TokenizeError";
  }
}

export class ParseError extends Error {
  constructor(message: string, public position: number) {
    super(`${message} at position ${position}`);
    this.name = "ParseError";
  }
}

/**
 * Converts an arithmetic expression string into a list of tokens.
 * Supports integers, decimals, and the operators + - * / ( ).
 */
export function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  const isDigit = (c: string) => c >= "0" && c <= "9";
  const isWhitespace = (c: string) =>
    c === " " || c === "\t" || c === "\n" || c === "\r";

  while (i < input.length) {
    const ch = input[i];

    if (isWhitespace(ch)) {
      i++;
      continue;
    }

    // Numbers, including decimals. A leading digit is required.
    if (isDigit(ch)) {
      const start = i;
      let seenDot = false;
      while (i < input.length) {
        const c = input[i];
        if (isDigit(c)) {
          i++;
        } else if (c === "." && !seenDot) {
          seenDot = true;
          i++;
        } else {
          break;
        }
      }
      const value = input.slice(start, i);
      // Guard against trailing dot like "1." producing non-numeric output.
      if (value.endsWith(".")) {
        throw new TokenizeError(`Malformed number '${value}'`, start);
      }
      tokens.push({ type: "NUMBER", value, position: start });
      continue;
    }

    const single: Record<string, TokenType> = {
      "+": "PLUS",
      "-": "MINUS",
      "*": "STAR",
      "/": "SLASH",
      "(": "LPAREN",
      ")": "RPAREN",
    };

    if (ch in single) {
      tokens.push({ type: single[ch], value: ch, position: i });
      i++;
      continue;
    }

    throw new TokenizeError(`Unexpected character '${ch}'`, i);
  }

  return tokens;
}

/**
 * Evaluates a stream of tokens using recursive descent, which encodes
 * operator precedence directly in the grammar:

 *   expression := term (( '+' | '-' ) term)*
 *   term       := factor (( '*' | '/' ) factor)*
 *   factor     := NUMBER | '(' expression ')' | '-' factor
 *
 * Handles unary minus (e.g. -5, -(3+4), 2 * -3) in `factor`.
 */
export function evaluateTokens(tokens: Token[]): number {
  let pos = 0;

  const peek = (): Token | undefined => tokens[pos];

  const expect = (type: TokenType): Token => {
    const tok = peek();
    if (!tok || tok.type !== type) {
      const got = tok ? tok.type : "EOF";
      const where = tok ? tok.position : tokens.length;
      throw new ParseError(`Expected ${type} but got ${got}`, where);
    }
    pos++;
    return tok;
  };

  // expression := term (("+" | "-") term)*
  const parseExpression = (): number => {
    let left = parseTerm();
    while (true) {
      const tok = peek();
      if (tok && tok.type === "PLUS") {
        pos++;
        left += parseTerm();
      } else if (tok && tok.type === "MINUS") {
        pos++;
        left -= parseTerm();
      } else {
        break;
      }
    }
    return left;
  };

  // term := factor (("*" | "/") factor)*
  const parseTerm = (): number => {
    let left = parseFactor();
    while (true) {
      const tok = peek();
      if (tok && tok.type === "STAR") {
        pos++;
        left *= parseFactor();
      } else if (tok && tok.type === "SLASH") {
        pos++;
        const divisor = parseFactor();
        if (divisor === 0) {
          const at = tok.position;
          throw new ParseError("Division by zero", at);
        }
        left /= divisor;
      } else {
        break;
      }
    }
    return left;
  };

  // factor := NUMBER | "(" expression ")" | "-" factor
  const parseFactor = (): number => {
    const tok = peek();
    if (!tok) {
      throw new ParseError("Unexpected end of input", pos);
    }
    if (tok.type === "NUMBER") {
      pos++;
      return parseFloat(tok.value);
    }
    if (tok.type === "MINUS") {
      pos++;
      return -parseFactor();
    }
    if (tok.type === "PLUS") {
      // Unary plus, harmless to support.
      pos++;
      return parseFactor();
    }
    if (tok.type === "LPAREN") {
      pos++;
      const value = parseExpression();
      expect("RPAREN");
      return value;
    }
    throw new ParseError(`Unexpected token ${tok.type}`, tok.position);
  };

  if (tokens.length === 0) {
    throw new ParseError("Empty expression", 0);
  }

  const result = parseExpression();
  if (pos < tokens.length) {
    const extra = tokens[pos];
    throw new ParseError(`Unexpected token ${extra.type}`, extra.position);
  }
  return result;
}

/** Convenience: tokenize + evaluate. */
export function evaluate(expression: string): number {
  return evaluateTokens(tokenize(expression));
}
```

