## Notes on the Design

- **Tokenizer** is a simple single-pass scanner that records source positions, which is what later lets `ParseError` report *where* things went wrong.
- **Parser** is recursive descent over the grammar `expression → term → factor`. Precedence falls out naturally: `term` is *inside* `expression`, so `*` and `/` bind tighter; left-associativity falls out of the `while` loops.
- **Unary operators** are handled in `factor` so they compose correctly with parentheses and other operators (`2 * -3`, `-(3+4)`).
- **Division by zero** is detected at evaluation time (not tokenization), because the divisor might only become zero after evaluating subexpressions (e.g. `10 / (5 - 5)`).
- **Empty input** is caught explicitly — without it, `parseExpression` would happily return `0` for an empty token stream, which would be a surprising edge case.

# Edit Distance with Edit Script in Go

Here's a production-ready implementation of Levenshtein distance that also reconstructs the edit script. I'll highlight the non-obvious parts as requested.

```go
// Package editdist computes Levenshtein edit distance and the corresponding
// edit script between two strings (or byte slices/runes).
package editdist

import "fmt"

// Op is a single edit operation.
type Op struct {
	Kind Kind // Insert, Delete, or Equal
	// Pos is the insertion point in the *source* string for all ops.
	// For Equal and Delete, Pos is the index in source of the affected rune.
	// For Insert, Pos is the index in source *before which* the new rune is inserted.
	Pos  int
	Rune rune // The rune inserted (Insert) or deleted (Delete). Unused for Equal.
}

type Kind uint8

const (
	Equal Kind = iota
	Delete
	Insert
)

func (k Kind) String() string {
	switch k {
	case Equal:
		return "="
	case Delete:
		return "-"
	case Insert:
		return "+"
	default:
		return "?"
	}
}

// Distance computes the Levenshtein distance between a and b using runes,
// which is what callers almost always want for human-facing text.
//
// TRICKY: We operate on []rune, not bytes. Byte-level Levenshtein gives
// nonsense for non-ASCII (e.g. "é" counts as 2 edits against "e"). The cost
// is one allocation per string; if you're hot-path-ing on ASCII-only inputs,
// call DistanceBytes.
func Distance(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	dist, _ := compute(ra, rb, false)
	return dist
}

// Script returns the edit distance and a script that transforms a into b.
// Insert/Delete ops are reported at the source position where they apply.
func Script(a, b string) (int, []Op) {
	ra, rb := []rune(a), []rune(b)
	return compute(ra, rb, true)
}

// compute is the shared kernel. When wantScript is false we skip the second
// row buffer needed for backtracking, saving ~half the memory on large inputs.
func compute(a, b []rune, wantScript bool) (int, []Op) {
	n, m := len(a), len(b)

	// TRICKY: Handle empties explicitly. The main loop below assumes both
	// dims >= 1 in places (e.g. i-1, j-1 indexing) and it makes the intent clear.
	if n == 0 {
		if !wantScript {
			return m, nil
		}
		ops := make([]Op, m)
		for j := 0; j < m; j++ {
			ops[j] = Op{Kind: Insert, Pos: 0, Rune: b[j]}
		}
		return m, ops
	}
	if m == 0 {
		if !wantScript {
			return n, nil
		}
		ops := make([]Op, n)
		for i := 0; i < n; i++ {
			ops[i] = Op{Kind: Delete, Pos: i, Rune: a[i]}
		}
		return n, ops
	}

	// TRICKY: Row-buffer approach. dp[j] holds d(i, j) for the current row.
	// For backtracking we need the full matrix, so we allocate it only if
	// asked. The two-buffer trick for the distance-only path avoids an
	// n*m allocation.
	if !wantScript {
		prev := make([]int, m+1)
		curr := make([]int, m+1)
		for j := 0; j <= m; j++ {
			prev[j] = j
		}
		for i := 1; i <= n; i++ {
			curr[0] = i
			ai := a[i-1]
			for j := 1; j <= m; j++ {
				cost := 1
				if ai == b[j-1] {
					cost = 0
				}
				// min(del, ins, sub) — written out for clarity/speed.
				v := prev[j-1] + cost
				if d := prev[j] + 1; d < v {
					v = d
				}
				if d := curr[j-1] + 1; d < v {
					v = d
				}
				curr[j] = v
			}
			prev, curr = curr, prev
		}
		return prev[m], nil
	}

	// Full-matrix path. dp is (n+1) x (m+1), stored row-major as [][]int for
	// simple backtracking indexing. For very large inputs consider packing
	// into a single []int32; the current form trades a bit of memory for
	// readability.
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}
	for i := 0; i <= n; i++ {
		dp[i][0] = i
	}
	for j := 0; j <= m; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= n; i++ {
		ai := a[i-1]
		row, up := dp[i], dp[i-1]
		for j := 1; j <= m; j++ {
			cost := 1
			if ai == b[j-1] {
				cost = 0
			}
			v := up[j-1] + cost
			if d := up[j] + 1; d < v {
				v = d
			}
			if d := row[j-1] + 1; d < v {
				v = d
			}
			row[j] = v
		}
	}

	// Backtrack from (n, m) to (0, 0). Build reversed, then reverse.
	//
	// TRICKY: Tie-breaking matters for script quality. When multiple moves
	// are optimal (e.g. substitution vs. delete+insert of the same letter),
	// we prefer the *diagonal* move (match/substitution) first, then delete,
	// then insert. This yields scripts that group substitutions sensibly
	// instead of interleaving delete/insert pairs. Any consistent tie-break
	// is correct w.r.t. distance, but this one reads better in diffs.
	ops := make([]Op, 0, dp[n][m])
	i, j := n, m
	for i > 0 || j > 0 {
		switch {
		case i > 0 && j > 0 && a[i-1] == b[j-1] && dp[i][j] == dp[i-1][j-1]:
			ops = append(ops, Op{Kind: Equal, Pos: i - 1, Rune: a[i-1]})
			i--
			j--
		case i > 0 && j > 0 && dp[i][j] == dp[i-1][j-1]+1:
			// Substitution: we encode it as Delete then Insert so callers see
			// primitives. Order matters: at the same Pos, Delete must come
			// before Insert to be applied sequentially against a mutable
			// working copy of the source.
			ops = append(ops, Op{Kind: Insert, Pos: i - 1, Rune: b[j-1]})
			ops = append(ops, Op{Kind: Delete, Pos: i - 1, Rune: a[i-1]})
			i--
			j--
		case i > 0 && dp[i][j] == dp[i-1][j]+1:
			ops = append(ops, Op{Kind: Delete, Pos: i - 1, Rune: a[i-1]})
			i--
		default:
			// j > 0 implied.
			//
			// TRICKY: For an Insert, the insertion point in source is i
			// (everything up to i is already matched), not i-1. At the time
			// of backtrack i can be 0 (inserting at the very start), which
			// is why we don't subtract 1 here.
			ops = append(ops, Op{Kind: Insert, Pos: i, Rune: b[j-1]})
			j--
		}
	}

	// Reverse in place.
	for l, r := 0, len(ops)-1; l < r; l, r = l+1, r-1 {
		ops[l], ops[r] = ops[r], ops[l]
	}

	return dp[n][m], ops
}

// Apply replays an edit script against the source runes and returns the
// resulting runes. Useful for verifying scripts in tests.
//
// TRICKY: Delete/Insert at the same Pos are order-sensitive — see the
// substitution comment in compute. We honor script order literally.
func Apply(a string, ops []Op) []rune {
	src := []rune(a)
	out := make([]rune, 0, len(src))
	cursor := 0
	for _, op := range ops {
		// Copy through any untouched source between cursor and op.Pos.
		for cursor < op.Pos && cursor < len(src) {
			out = append(out, src[cursor])
			cursor++
		}
		switch op.Kind {
		case Equal:
			out = append(out, op.Rune)
			cursor++
		case Delete:
			cursor++
		case Insert:
			out = append(out, op.Rune)
		}
	}
	for cursor < len(src) {
		out = append(out, src[cursor])
		cursor++
	}
	return out
}

// String renders an edit script human-readably (Handy for logging/debug).
func (op Op) String() string {
	switch op.Kind {
	case Equal:
		return fmt.Sprintf("('%c', =)", op.Rune)
	case Delete:
		return fmt.Sprintf("('%c', -)", op.Rune)
	case Insert:
		return fmt.Sprintf("('%c', +)", op.Rune)
	}
	return "?"
}
```

## The tricky parts, at a glance

1. **Rune-level, not byte-level.** Byte-level Levenshtein is wrong for any non-ASCII input, and `range` on a string gives runes anyway — doing it byte-wise would be both incorrect and surprising. We pay one `[]rune` allocation per string. If you truly need ASCII-only, add a `DistanceBytes` variant; don't skip runes for "speed".

2. **Two memory paths.** Distance-only uses two `int` row buffers (O(m) memory). With a script you need the full `(n+1)×(m+1)` matrix for backtracking (O(n·m)). This matters at production scales: a 10k×10k pair is ~800 MB in `[][]int`. If you routinely diff huge strings, replace `[][]int` with a packed `[]int32` (still 400 MB at 10k×10k) or switch to Hirschberg's algorithm (O(min(n,m)) memory) — but expect a constant-factor slowdown.

3. **Tie-breaking in backtrack.** Multiple predecessor cells can achieve the optimal cost. We prefer **diagonal** (match/substitution) > **delete** > **insert**. Any consistent ordering yields a valid optimal script, but differencing tools care: without this, you get "delete-everything then insert-everything" garbage scripts. This is not a performance decision; it's a correctness-of-usability decision.

4. **Substitutions as Delete+Insert.** We don't have a `Substitute` op; a substitution becomes a `Delete` at `Pos:i-1` immediately followed by an `Insert` at `Pos:i-1` (with the *old unedited* coordinate — see below). This keeps the script made of primitives, but makes **script order semantically significant**: when replaying against a mutable buffer, the Delete must precede the Insert at the same position. Document that if you expose the script.

5. **`Pos` coordinate stability.** Every `Pos` is an index into the **original source**, not the working buffer. For `Insert`, `Pos` is the source index *before which* the rune goes; for `Delete`/`Equal`, `Pos` is the source index of the rune. This makes the script self-describing and order-independent for consumers that filter (`Apply` relies on this). The subtle bug you avoid: if you emitted mutated-buffer positions, `Insert` at the same `Pos` as a `Delete` would drift by one.

6. **Empty-input fast path.** `n == 0` or `m == 0` is handled before indexing into `dp`, avoiding off-by-one corner cases in the backtrack loop.

7. **`Apply` uses `cursor`, not `i`.** It copies untouched source spans between scripted positions. `Equal` and `Delete` advance the cursor; `Insert` doesn't. That's the invariant that makes the whole scheme type-check (`cursor` can never overtake `op.Pos`).

8. **No `Equal` ops for size-only queries.** In `wantScript == false` we never allocate `ops`; the return is `(dist, nil)`, so callers must tolerate `nil` slices.

Compared to a plain DP solution this is the same algorithmic complexity — O(n·m) time, O(min(n,m)) or O(n·m) memory — but the choices above are what separates a working function from one you'd want in production.

Below is a CUDA C++ implementation of a parallel topological sort using Kahn’s algorithm. It reports a cycle when the number of processed vertices is less than the number of vertices.

The implementation builds a CSR adjacency list on the host, then runs the sort on the GPU. The unit tests use a small assertion-based harness so they compile with `nvcc` without extra test dependencies.

```cpp
// topo_sort_cuda.cu
//
// Compile:
//   nvcc -std=c++17 topo_sort_cuda.cu -o topo_sort_cuda
// Run:
//   ./topo_sort_cuda

#include <cuda_runtime.h>
#include <thrust/copy.h>
#include <thrust/device_vector.h>
#include <thrust/fill.h>

#include <algorithm>
#include <cassert>
#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

#define CUDA_CHECK(call)                                                        \
  do {                                                                          \
    cudaError_t err__ = (call);                                                 \
    if (err__ != cudaSuccess) {                                                 \
      throw std::runtime_error(std::string("CUDA error: ") +                    \
                               cudaGetErrorString(err__));                       \
    }                                                                           \
  } while (0)

struct TopoSortResult {
  bool has_cycle = false;
  // If has_cycle == false, this is a full topological order.
  // If has_cycle == true, this contains the vertices that could be processed
  // before the cycle was detected. It is not a valid topological order.
  std::vector<int> order;
};

__global__ void compute_indegree_kernel(int n,
                                        const int* row_ptr,
                                        const int* col_idx,
                                        int* indegree) {
  int u = blockIdx.x * blockDim.x + threadIdx.x;
  if (u >= n) return;

  for (int e = row_ptr[u]; e < row_ptr[u + 1]; ++e) {
    int v = col_idx[e];
    atomicAdd(&indegree[v], 1);
  }
}

__global__ void build_initial_frontier_kernel(int n,
                                              const int* indegree,
                                              int* frontier,
                                              int* frontier_size) {
  int v = blockIdx.x * blockDim.x + threadIdx.x;
  if (v >= n) return;

  if (indegree[v] == 0) {
    int pos = atomicAdd(frontier_size, 1);
    frontier[pos] = v;
  }
}

__global__ void process_frontier_kernel(int frontier_size,
                                        const int* frontier,
                                        const int* row_ptr,
                                        const int* col_idx,
                                        int* indegree,
                                        int* next_frontier,
                                        int* next_size,
                                        int* order,
                                        int* processed) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= frontier_size) return;

  int u = frontier[i];

  int order_pos = atomicAdd(processed, 1);
  order[order_pos] = u;

  for (int e = row_ptr[u]; e < row_ptr[u + 1]; ++e) {
    int v = col_idx[e];

    // old == 1 means indegree[v] becomes 0 after this decrement.
    int old = atomicAdd(&indegree[v], -1);
    if (old == 1) {
      int pos = atomicAdd(next_size, 1);
      next_frontier[pos] = v;
    }
  }
}

TopoSortResult topological_sort_cuda(
    int n,
    const std::vector<std::pair<int, int>>& edges) {
  for (const auto& e : edges) {
    if (e.first < 0 || e.first >= n || e.second < 0 || e.second >= n) {
      throw std::invalid_argument("edge endpoint out of range");
    }
  }

  TopoSortResult result;

  if (n == 0) {
    result.has_cycle = false;
    return result;
  }

  // Build CSR adjacency list on the host.
  std::vector<int> row_ptr(n + 1, 0);
  for (const auto& e : edges) {
    row_ptr[e.first + 1]++;
  }

  for (int i = 0; i < n; ++i) {
    row_ptr[i + 1] += row_ptr[i];
  }

  std::vector<int> col_idx(edges.size());
  std::vector<int> cursor = row_ptr;
  for (const auto& e : edges) {
    int u = e.first;
    int v = e.second;
    col_idx[cursor[u]++] = v;
  }

  thrust::device_vector<int> d_row_ptr(row_ptr.begin(), row_ptr.end());
  thrust::device_vector<int> d_col_idx(col_idx.begin(), col_idx.end());
  thrust::device_vector<int> d_indegree(n, 0);

  thrust::device_vector<int> d_frontier(n);
  thrust::device_vector<int> d_next_frontier(n);
  thrust::device_vector<int> d_order(n);

  thrust::device_vector<int> d_frontier_size(1, 0);
  thrust::device_vector<int> d_next_size(1, 0);
  thrust::device_vector<int> d_processed(1, 0);

  constexpr int kThreads = 256;
  int blocks = (n + kThreads - 1) / kThreads;

  compute_indegree_kernel<<<blocks, kThreads>>>(
      n,
      d_row_ptr.data().get(),
      d_col_idx.data().get(),
      d_indegree.data().get());
  CUDA_CHECK(cudaGetLastError());

  build_initial_frontier_kernel<<<blocks, kThreads>>>(
      n,
      d_indegree.data().get(),
      d_frontier.data().get(),
      d_frontier_size.data().get());
  CUDA_CHECK(cudaGetLastError());

  int frontier_size = 0;
  CUDA_CHECK(cudaMemcpy(&frontier_size,
                        d_frontier_size.data().get(),
                        sizeof(int),
                        cudaMemcpyDeviceToHost));

  while (frontier_size > 0) {
    thrust::fill(d_next_size.begin(), d_next_size.end(), 0);

    int frontier_blocks = (frontier_size + kThreads - 1) / kThreads;

    process_frontier_kernel<<<frontier_blocks, kThreads>>>(
        frontier_size,
        d_frontier.data().get(),
        d_row_ptr.data().get(),
        d_col_idx.data().get(),
        d_indegree.data().get(),
        d_next_frontier.data().get(),
        d_next_size.data().get(),
        d_order.data().get(),
        d_processed.data().get());
    CUDA_CHECK(cudaGetLastError());

    CUDA_CHECK(cudaMemcpy(&frontier_size,
                          d_next_size.data().get(),
                          sizeof(int),
                          cudaMemcpyDeviceToHost));

    d_frontier.swap(d_next_frontier);
  }

  int processed = 0;
  CUDA_CHECK(cudaMemcpy(&processed,
                        d_processed.data().get(),
                        sizeof(int),
                        cudaMemcpyDeviceToHost));

  result.has_cycle = (processed != n);

  if (!result.has_cycle) {
    result.order.resize(n);
    thrust::copy(d_order.begin(), d_order.end(), result.order.begin());
  } else {
    result.order.resize(processed);
    thrust::copy(d_order.begin(), d_order.begin() + processed,
                 result.order.begin());
  }

  return result;
}

// -----------------------------------------------------------------------------
// Test helpers
// -----------------------------------------------------------------------------

bool is_valid_topological_order(
    int n,
    const std::vector<std::pair<int, int>>& edges,
    const std::vector<int>& order) {
  if (static_cast<int>(order.size()) != n) return false;

  std::vector<int> position(n, -1);
  for (int i = 0; i < n; ++i) {
    if (order[i] < 0 || order[i] >= n) return false;
    if (position[order[i]] != -1) return false;
    position[order[i]] = i;
  }

  for (const auto& e : edges) {
    int u = e.first;
    int v = e.second;
    if (position[u] >= position[v]) return false;
  }

  return true;
}

void expect_no_cycle(int n, const std::vector<std::pair<int, int>>& edges) {
  TopoSortResult result = topological_sort_cuda(n, edges);

  if (result.has_cycle) {
    throw std::runtime_error("expected no cycle, but cycle was reported");
  }

  if (!is_valid_topological_order(n, edges, result.order)) {
    throw std::runtime_error("invalid topological order returned");
  }
}

void expect_cycle(int n, const std::vector<std::pair<int, int>>& edges) {
  TopoSortResult result = topological_sort_cuda(n, edges);

  if (!result.has_cycle) {
    throw std::runtime_error("expected cycle, but no cycle was reported");
  }
}

// -----------------------------------------------------------------------------
// Unit tests
// -----------------------------------------------------------------------------

void test_empty_graph() {
  auto result = topological_sort_cuda(0, {});
  assert(!result.has_cycle);
  assert(result.order.empty());
}

void test_single_vertex_no_edges() {
  expect_no_cycle(1, {});
}

void test_single_vertex_self_loop_is_cycle() {
  expect_cycle(1, {{0, 0}});
}

void test_simple_chain() {
  expect_no_cycle(4, {{0, 1}, {1, 2}, {2, 3}});
}

void test_disconnected_dag() {
  expect_no_cycle(6, {
    {0, 1},
    {1, 2},
    {3, 4},
    // vertex 5 is isolated
  });
}

void test_diamond_dag() {
  expect_no_cycle(4, {
    {0, 1},
    {0, 2},
    {1, 3},
    {2, 3},
  });
}

void test_two_vertex_cycle() {
  expect_cycle(2, {{0, 1}, {1, 0}});
}

void test_three_vertex_cycle() {
  expect_cycle(3, {{0, 1}, {1, 2}, {2, 0}});
}

void test_cycle_with_acyclic_part() {
  // 0 -> 1 -> 2 -> 3, and 4 <-> 5 is a cycle.
  // Vertices 0,1,2,3 may be processed, but the graph still has a cycle.
  expect_cycle(6, {
    {0, 1},
    {1, 2},
    {2, 3},
    {4, 5},
    {5, 4},
  });

