    let mid = a.len() / 2;
    let (left, right) = a.split_at_mut(mid);

    rayon::join(|| prefix_sum(left), || prefix_sum(right));

    let left_sum = left[left.len() - 1];
    right.par_iter_mut().for_each(|x| *x += left_sum);
}
