Here's a Rust implementation of topological sort that detects cycles using Kahn's algorithm:

```rust
use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

/// Result of a topological sort attempt.
#[derive(Debug, PartialEq, Eq)]
pub enum TopoError {
    /// The graph contains a cycle; the returned nodes form the cyclic remainder.
    Cycle(Vec<usize>),
    /// The graph references a node index that doesn't exist.
    MissingNode(usize),
}

/// Performs a topological sort using Kahn's algorithm.
///
/// Returns the nodes in topological order, or `TopoError::Cycle` if the graph
/// contains a cycle.
pub fn topological_sort(adjacency: &[Vec<usize>]) -> Result<Vec<usize>, TopoError> {
    let n = adjacency.len();

    // Validate all referenced indices exist.
    for (from, edges) in adjacency.iter().enumerate() {
        for &to in edges {
            if to >= n {
                return Err(TopoError::MissingNode(to));
            }
            let _ = from;
        }
    }

    // Compute in-degree for each node.
    let mut in_degree = vec![0usize; n];
    for edges in adjacency {
        for &to in edges {
            in_degree[to] += 1;
        }
    }

    // Seed the queue with all nodes that have no incoming edges.
    let mut queue: VecDeque<usize> = in_degree
        .iter()
        .enumerate()
        .filter(|&(_, &d)| d == 0)
        .map(|(i, _)| i)
        .collect();

    let mut order = Vec::with_capacity(n);

    while let Some(node) = queue.pop_front() {
        order.push(node);
        for &next in &adjacency[node] {
            in_degree[next] -= 1;
            if in_degree[next] == 0 {
                queue.push_back(next);
            }
        }
    }

    if order.len() == n {
        Ok(order)
    } else {
        // Any nodes still with in_degree > 0 are part of (or downstream of) a cycle.
        let cyclic: Vec<usize> = in_degree
            .iter()
            .enumerate()
            .filter(|&(_, &d)| d > 0)
            .map(|(i, _)| i)
            .collect();
        Err(TopoError::Cycle(cyclic))
    }
}

/// Convenience wrapper for named graphs.
pub fn topological_sort_named<T: Eq + Hash + Clone>(
    edges: &[(T, T)],
) -> Result<Vec<T>, CycleError<T>> {
    let mut index: HashMap<T, usize> = HashMap::new();
    let mut names: Vec<T> = Vec::new();

    let mut get_id = |node: &T| -> usize {
        if let Some(&i) = index.get(node) {
            i
        } else {
            let i = names.len();
            index.insert(node.clone(), i);
            names.push(node.clone());
            i
        }
    };

    // Build an edge list with stable indices.
    let mut edges_by_id: Vec<(usize, usize)> = Vec::with_capacity(edges.len());
    for (from, to) in edges {
        let f = get_id(from);
        let t = get_id(to);
        edges_by_id.push((f, t));
    }

    let mut adjacency = vec![Vec::new(); names.len()];
    for (f, t) in edges_by_id {
        adjacency[f].push(t);
    }

    match topological_sort(&adjacency) {
        Ok(order) => Ok(order.into_iter().map(|i| names[i].clone()).collect()),
        Err(TopoError::Cycle(ids)) => Err(CycleError {
            nodes: ids.into_iter().map(|i| names[i].clone()).collect(),
        }),
        Err(TopoError::MissingNode(i)) => unreachable!("bad index {i}"),
    }
}

#[derive(Debug)]
pub struct CycleError<T> {
    pub nodes: Vec<T>,
}

fn main() {
    // Example 1: a valid DAG.
    // Edges: 0->1, 0->2, 1->3, 2->3
    let dag = vec![
        vec![1, 2], // 0
        vec![3],    // 1
        vec![3],    // 2
        vec![],     // 3
    ];
    assert_eq!(topological_sort(&dag), Ok(vec![0, 1, 2, 3]));
    println!("DAG order: {:?}", topological_sort(&dag).unwrap());

    // Example 2: a cycle 0 -> 1 -> 2 -> 0.
    let cyclic = vec![
        vec![1], // 0 -> 1
        vec![2], // 1 -> 2
        vec![0], // 2 -> 0
    ];
    match topological_sort(&cyclic) {
        Ok(_) => unreachable!(),
        Err(TopoError::Cycle(nodes)) => {
            println!("Cycle detected among nodes: {:?}", nodes);
        }
        Err(e) => println!("Unexpected error: {e:?}"),
    }

    // Example 3: named nodes via the convenience wrapper.
    let tasks = vec![
        ("bake", "decorate"),
        ("shop", "bake"),
        ("shop", "decorate"),
    ];
    println!("Task order: {:?}", topological_sort_named(&tasks).unwrap());
}
```

### How it works

1. **In-degree counting** — for each node, count how many edges point *into* it.
2. **Queue of zero-in-degree nodes** — any node with no incoming edges can safely go first.
3. **Pop and decrement** — when a node is emitted, decrement the in-degree of its successors; when a successor hits zero, enqueue it.
4. **Cycle detection** — if fewer than `n` nodes are emitted, the remaining nodes (those with `in_degree > 0`) are exactly the nodes involved in one or more cycles.

### Output

```
DAG order: [0, 1, 2, 3]
Cycle detected among nodes: [0, 1, 2]
Task order: ["shop", "bake", "decorate"]
```

Notes:
- Complexity is **O(V + E)** time and **O(V + E)** space.
- The `Cycle` variant returns the nodes that *remain* after the algorithm stalls — they identify the cycle (and anything only reachable through it), so you can report specific offending nodes rather than a generic error.
- The named wrapper is convenient for real programs where vertices are strings or other keys; it maps them through an internal integer index automatically.

```rust
/// Merges overlapping intervals and returns them sorted by start.
/// Assumes intervals are closed: [start, end].
pub fn merge_intervals(mut intervals: Vec<(i32, i32)>) -> Vec<(i32, i32)> {
    if intervals.is_empty() {
        return Vec::new();
    }

    // Sort by start value.
    intervals.sort_unstable_by_key(|&(start, _)| start);

    let mut merged = Vec::with_capacity(intervals.len());

    let (mut cur_start, mut cur_end) = intervals[0];

    for &(start, end) in &intervals[1..] {
        if start <= cur_end {
            // Overlapping or touching, so merge.
            cur_end = cur_end.max(end);
        } else {
            // No overlap, push current interval and start a new one.
            merged.push((cur_start, cur_end));
            cur_start = start;
            cur_end = end;
        }
    }

    merged.push((cur_start, cur_end));
    merged
}

fn main() {
    let intervals = vec![(1, 3), (2, 6), (8, 10), (15, 18)];
    assert_eq!(
        merge_intervals(intervals),
        vec![(1, 6), (8, 10), (15, 18)]
    );
}
```

### How it works

1. Sort intervals by their start value.
2. Iterate through the sorted intervals.
3. If the next interval starts before or at the current interval’s end, they overlap, so extend the current interval’s end if needed.
4. Otherwise, push the current interval into the result and start tracking the next interval.

### Complexity

- **Time:** `O(n log n)` because sorting dominates. The merge pass is `O(n)`.
- **Space:** `O(n)` for the returned merged intervals. Apart from the output, the algorithm uses `O(1)` extra state, plus any auxiliary space used internally by Rust’s sorting implementation.

For half-open intervals `[start, end)`, change the overlap check from `start <= cur_end` to `start < cur_end`.

