fn merge_intervals(mut v: Vec<(i32, i32)>) -> Vec<(i32, i32)> {
    v.sort_unstable_by_key(|x| x.0);
    let mut out = Vec::new();

    for (s, e) in v {
        if let Some(last) = out.last_mut() {
            if s <= last.1 {
                last.1 = last.1.max(e);
                continue;
            }
        }
        out.push((s, e));
    }
    out
}
```

