```kotlin
import kotlin.random.Random

class SkipList<T : Comparable<T>>(
    private val maxLevel: Int = 16,
    private val probability: Double = 0.5
) {
    private class Node<T>(val value: T?, val height: Int) {
        val forward: Array<Node<T>?> = arrayOfNulls(height)
    }

    private val head = Node<T>(null, maxLevel)
    private var level = 1
    private var count = 0
    private val random = Random.Default

    val size: Int
        get() = count

    private fun randomLevel(): Int {
        var lvl = 1
        while (random.nextDouble() < probability && lvl < maxLevel) {
            lvl++
        }
        return lvl
    }

    fun search(value: T): Boolean {
        var current = head

        for (i in level - 1 downTo 0) {
            while (true) {
                val next = current.forward[i] ?: break
                if (next.value!!.compareTo(value) < 0) {
                    current = next
                } else {
                    break
                }
            }
        }

        val candidate = current.forward[0] ?: return false
        return candidate.value == value
    }

    fun insert(value: T): Boolean {
        val update = arrayOfNulls<Node<T>>(maxLevel)
        var current = head

        for (i in level - 1 downTo 0) {
            while (true) {
                val next = current.forward[i] ?: break
                if (next.value!!.compareTo(value) < 0) {
                    current = next
                } else {
                    break
                }
            }
            update[i] = current
        }

        val next = current.forward[0]
        if (next != null && next.value == value) {
            return false // No duplicates
        }

        val newHeight = randomLevel()
        if (newHeight > level) {
            for (i in level until newHeight) {
                update[i] = head
            }
            level = newHeight
        }

        val newNode = Node(value, newHeight)
        for (i in 0 until newHeight) {
            newNode.forward[i] = update[i]!!.forward[i]
            update[i]!!.forward[i] = newNode
        }

        count++
        return true
    }

    fun delete(value: T): Boolean {
        val update = arrayOfNulls<Node<T>>(maxLevel)
        var current = head

        for (i in level - 1 downTo 0) {
            while (true) {
                val next = current.forward[i] ?: break
                if (next.value!!.compareTo(value) < 0) {
                    current = next
                } else {
                    break
                }
            }
            update[i] = current
        }

        val target = current.forward[0]
        if (target == null || target.value != value) {
            return false
        }

        for (i in 0 until target.height) {
            update[i]!!.forward[i] = target.forward[i]
        }

        while (level > 1 && head.forward[level - 1] == null) {
            level--
        }

        count--
        return true
    }
}

fun main() {
    val skipList = SkipList<Int>()

    skipList.insert(10)
    skipList.insert(20)
    skipList.insert(15)
    skipList.insert(30)

    println(skipList.search(15)) // true
    println(skipList.search(25)) // false

    println(skipList.delete(20)) // true
    println(skipList.search(20)) // false

    println(skipList.size)       // 3
}
```

