# Exponential Backoff Retry with Jitter (Swift)

```swift
import Foundation

// MARK: - Retry Configuration

struct RetryPolicy {
    /// Maximum number of attempts (including the initial one).
    var maxAttempts: Int = 5
    /// Base delay in seconds for the first retry.
    var baseDelay: TimeInterval = 0.5
    /// Multiplier applied to the delay after each failure.
    var multiplier: Double = 2.0
    /// Maximum delay cap in seconds.
    var maxDelay: TimeInterval = 30.0
    /// Jitter strategy. Uses "full jitter" by default (delay is uniform in [0, delay]).
    var jitter: JitterStrategy = .full

    enum JitterStrategy {
        case none       // no jitter, pure exponential backoff
        case full       // random in [0, delay]
        case equal      // delay/2 + random(0...delay/2)
        case decorrelated // random in [baseDelay, previousDelay * 3]
    }
}

// MARK: - Retry Error

enum RetryError: Error {
    /// All retry attempts failed. Contains the last error thrown.
    case exhausted(attempts: Int, lastError: Error)
}

// MARK: - Retry Wrapper

/// Executes an async throwing operation with exponential backoff and jitter.
/// - Parameters:
///   - policy: Retry/backoff configuration.
///   - shouldRetry: Optional predicate to decide if a specific error is retryable.
///   - operation: The async throwing operation to run.
func withRetry<T>(
    policy: RetryPolicy = RetryPolicy(),
    shouldRetry: (Error) -> Bool = { _ in true },
    operation: () async throws -> T
) async throws -> T {
    precondition(policy.maxAttempts >= 1, "maxAttempts must be >= 1")

    var previousDelay: TimeInterval = policy.baseDelay

    for attempt in 1...policy.maxAttempts {
        do {
            return try await operation()
        } catch {
            // If the caller says "don't retry this", bail out immediately.
            guard shouldRetry(error) else { throw error }

            // Last attempt: wrap and throw.
            guard attempt < policy.maxAttempts else {
                throw RetryError.exhausted(attempts: attempt, lastError: error)
            }

            let delay = computeDelay(
                attempt: attempt,
                policy: policy,
                previousDelay: previousDelay
            )
            previousDelay = delay

            try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
        }
    }

    // Unreachable; loop either returns or throws.
    fatalError("Unreachable")
}

// MARK: - Delay Calculation

private func computeDelay(
    attempt: Int,
    policy: RetryPolicy,
    previousDelay: TimeInterval
) -> TimeInterval {
    // Exponential component: base * multiplier^(attempt - 1)
    let exponential = policy.baseDelay * pow(policy.multiplier, Double(attempt - 1))
    let capped = min(exponential, policy.maxDelay)

    switch policy.jitter {
    case .none:
        return capped
    case .full:
        return Double.random(in: 0...capped)
    case .equal:
        let half = capped / 2
        return half + Double.random(in: 0...half)
    case .decorrelated:
        let upper = max(capped, previousDelay * 3)
        return Double.random(in: policy.baseDelay...upper)
    }
}
```

## Usage Example

```swift
// --- A flaky async operation (fails first two calls) ---
actor FlakyService {
    private var callCount = 0

    func fetchData() async throws -> String {
        callCount += 1
        if callCount < 3 {
            throw URLError(.timedOut)
        }
        return "Success on attempt \(callCount)"
    }
}

let service = FlakyService()

// --- Retry only on transient network errors ---
let policy = RetryPolicy(
    maxAttempts: 5,
    baseDelay: 0.3,
    multiplier: 2.0,
    maxDelay: 5.0,
    jitter: .full
)

do {
    let result = try await withRetry(
        policy: policy,
        shouldRetry: { error in
            guard let urlError = error as? URLError else { return false }
            return urlError.code == .timedOut
        }
    ) {
        try await service.fetchData()
    }
    print(result)  // "Success on attempt 3"
} catch let RetryError.exhausted(attempts, lastError) {
    print("Gave up after \(attempts) attempts. Last error: \(lastError)")
} catch {
    print("Non-retryable error: \(error)")
}
```

## Notes / Design Choices

- **Full jitter** (`Double.random(in: 0...delay)`) is the default because it minimizes thundering-herd effects best (see AWS's "Exponential Backoff and Jitter" article).
- **`shouldRetry` predicate** lets you bail out on non-transient errors (e.g., 400 responses, decoding errors) instead of wasting attempts.
- **Jitter variants** are provided so you can match the strategy used elsewhere in your system (`equal`, `decorrelated`).
- **`maxDelay` cap** prevents runaway waits on long retry chains.
- **`Task.sleep`** cancels cleanly if the surrounding `Task` is cancelled.
- To use structured concurrency cancellation propagation, call this from within a cancelled-aware context; `Task.sleep` will throw `CancellationError` on cancel.

```rust
/// Parses an integer-only ISO-8601 duration subset:
/// `P[nD][T[nH][nM][nS]]`
/// Examples: "P3DT4H5M", "PT30S", "P2D"
/// Returns total seconds, or None on invalid input / overflow.
fn parse_iso8601_duration_secs(s: &str) -> Option<u64> {
    let mut rest = s.strip_prefix('P')?;
    if rest.is_empty() {
        return None;
    }

    let mut total = 0u64;
    let mut last_rank = 0u8; // D=1, H=2, M=3, S=4
    let mut saw_t = false;
    let mut saw_component = false;

    while !rest.is_empty() {
        if rest.starts_with('T') {
            if saw_t {
                return None;
            }
            saw_t = true;
            rest = &rest[1..];
            if rest.is_empty() {
                return None;
            }
            continue;
        }

        let (n, r) = parse_u64_digits(rest)?;
        rest = r;

        let ch = rest.chars().next()?;
        let (rank, multiplier) = match ch {
            'D' if !saw_t => (1, 86_400),
            'H' if saw_t => (2, 3_600),
            'M' if saw_t => (3, 60),
            'S' if saw_t => (4, 1),
            _ => return None,
        };

        if rank <= last_rank {
            return None;
        }
        last_rank = rank;

        total = total.checked_add(n.checked_mul(multiplier)?)?;
        rest = &rest[1..];
        saw_component = true;
    }

    if saw_component { Some(total) } else { None }
}

fn parse_u64_digits(s: &str) -> Option<(u64, &str)> {
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut value = 0u64;

    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value
            .checked_mul(10)?
            .checked_add((bytes[i] - b'0') as u64)?;
        i += 1;
    }

    if i == 0 {
        None
    } else {
        Some((value, &s[i..]))
    }
}
```

