## Notes on Design Decisions

| Choice | Reason |
|--------|--------|
| **Years = 365 days, months = 30 days** | ISO 8601 defines calendar units ambiguously; this is the widely-used "estimated" convention (also what `Duration.parse` on `java.time` does *not* support, but `Period` does). If you need calendar-accurate semantics, use `java.time.Period` + a reference date instead. |
| **`require` for preconditions** | Fails fast with `IllegalArgumentException`, matching arithmetic-function Kotlin idioms (`String.toLong()` throws the same way). |
| **Uppercase only** | The ISO 8601 standard specifies uppercase designators. Lowercase is explicitly *not* ISO 8601, so rejecting it keeps the contract honest. |
| **`Long` return type** | Avoids overflow up to ~292 billion years of seconds. |
| **Throws vs. nullable return** | A `null` return hides the reason for failure; throwing lets the caller decide whether a malformed duration is exceptional. |

If you'd prefer a **nullable** API instead (`fun parse(...): Long?`), swap each `require` for `return null` — the tests would then assert `null` via `assertNull` instead of `assertFailsWith`.

```ts
export type TopoResult = {
  order: string[];
  cycle: string[] | null;
};

/**
 * Returns a topological ordering, or a cycle if one exists.
 * If a cycle is found, `cycle` contains the cycle path with the
 * starting node repeated at the end, e.g. ["a", "b", "c", "a"].
 */
export function topologicalSort(graph: Record<string, string[]>): TopoResult {
  const nodes = new Set<string>();

  for (const [from, tos] of Object.entries(graph)) {
    nodes.add(from);
    for (const to of tos) nodes.add(to);
  }

  // 0 = unvisited, 1 = visiting, 2 = visited
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];
  const order: string[] = [];
  let cycle: string[] | null = null;

  const dfs = (node: string): boolean => {
    state.set(node, 1);
    stack.push(node);

    for (const next of graph[node] ?? []) {
      const nextState = state.get(next) ?? 0;

      if (nextState === 0) {
        if (dfs(next)) return true;
      } else if (nextState === 1) {
        const cycleStart = stack.indexOf(next);
        cycle = [...stack.slice(cycleStart), next];
        return true;
      }
    }

    stack.pop();
    state.set(node, 2);
    order.push(node);
    return false;
  };

  for (const node of nodes) {
    if ((state.get(node) ?? 0) === 0) {
      if (dfs(node)) break;
    }
  }

  if (cycle) {
    return { order: [], cycle };
  }

  return { order: order.reverse(), cycle: null };
}
```

