export function topoSort(graph: Record<string, string[]>): { order: string[]; cycle: string[] | null } {
  const nodes = new Set<string>();
  for (const [from, tos] of Object.entries(graph)) {
    nodes.add(from);
    tos.forEach((t) => nodes.add(t));
  }

  const state = new Map<string, 0 | 1 | 2>();
  const path: string[] = [];
  const order: string[] = [];

  function dfs(node: string): string[] | null {
    state.set(node, 1);
    path.push(node);

    for (const next of graph[node] ?? []) {
      const s = state.get(next) ?? 0;
      if (s === 0) {
        const cycle = dfs(next);
        if (cycle) return cycle;
      } else if (s === 1) {
        return [...path.slice(path.indexOf(next)), next];
      }
    }

    path.pop();
    state.set(node, 2);
    order.push(node);
    return null;
  }

  for (const node of nodes) {
    if (!state.get(node)) {
      const cycle = dfs(node);
      if (cycle) return { order: [], cycle };
    }
  }
  return { order: order.reverse(), cycle: null };
}

