#include <cuda_runtime.h>

// Single-threaded device-side LRU cache.
// Average O(1) get/put via hash-bucket chaining + doubly-linked LRU list.
// Not thread-safe: use one cache per thread, or guard get/put with a lock.

template <int CAP, int NBUCKETS>
struct DeviceLRU {
    int key[CAP], val[CAP];
    int prev[CAP], next[CAP];       // LRU list
    int hprev[CAP], hnext[CAP];    // hash bucket chain
    int bucket[NBUCKETS];
    int freeList, head, tail;

    __device__ __forceinline__ unsigned hash(int k) const {
        return (static_cast<unsigned>(k) * 2654435761u) % NBUCKETS;
    }

    __device__ void init() {
        head = tail = -1;
        for (int i = 0; i < NBUCKETS; ++i) bucket[i] = -1;
        for (int i = 0; i < CAP; ++i) {
            prev[i] = next[i] = -1;
            hprev[i] = hnext[i] = -1;
        }
        for (int i = 0; i < CAP - 1; ++i) next[i] = i + 1;
        next[CAP - 1] = -1;
        freeList = 0;
    }

    __device__ __forceinline__ int find(int k) const {
        unsigned h = hash(k);
        for (int i = bucket[h]; i != -1; i = hnext[i])
            if (key[i] == k) return i;
        return -1;
    }

    __device__ __forceinline__ void hashInsert(int i) {
        unsigned h = hash(key[i]);
        hprev[i] = -1;
        hnext[i] = bucket[h];
        if (bucket[h] != -1) hprev[bucket[h]] = i;
        bucket[h] = i;
    }

    __device__ __forceinline__ void hashRemove(int i) {
        unsigned h = hash(key[i]);
        if (hprev[i] != -1) hnext[hprev[i]] = hnext[i];
        else bucket[h] = hnext[i];
        if (hnext[i] != -1) hprev[hnext[i]] = hprev[i];
    }

    __device__ __forceinline__ void lruUnlink(int i) {
        int p = prev[i], n = next[i];
        if (p != -1) next[p] = n; else head = n;
        if (n != -1) prev[n] = p; else tail = p;
        prev[i] = next[i] = -1;
    }

    __device__ __forceinline__ void lruPushFront(int i) {
        prev[i] = -1;
        next[i] = head;
        if (head != -1) prev[head] = i;
        head = i;
        if (tail == -1) tail = i;
    }

    __device__ __forceinline__ int allocNode() {
        int i;
        if (freeList != -1) {
            i = freeList;
            freeList = next[i];
        } else {
            i = tail;              // evict least-recently-used
            hashRemove(i);
            lruUnlink(i);
        }
        return i;
    }

    __device__ bool get(int k, int& out) {
        int i = find(k);
        if (i == -1) return false;
        out = val[i];
        lruUnlink(i);
        lruPushFront(i);
        return true;
    }

    __device__ void put(int k, int v) {
        int i = find(k);
        if (i != -1) {
            val[i] = v;
            lruUnlink(i);
            lruPushFront(i);
            return;
        }

        i = allocNode();
        key[i] = k;
        val[i] = v;
        hashInsert(i);
        lruPushFront(i);
    }
};
```

Two ways it could fail under load:

1. **Data races if shared across CUDA threads.**  
   `get` and `put` mutate the LRU list and hash chains without synchronization. Concurrent calls can corrupt `prev/next`, `hprev/hnext`, or `bucket`, producing infinite loops, lost entries, or evicting a node another thread is using. A single global lock fixes correctness but can become a severe serialization bottleneck under load.

2. **Hash collisions / capacity thrashing.**  
   The code is O(1) only on average. If many keys hash to the same bucket, `find` degrades toward a linear scan of that bucket. Also, if the working set exceeds `CAP`, the cache constantly evicts and reloads entries, so hit rate collapses even though per-operation bookkeeping remains cheap.

