// unionfind.go
package unionfind

import "fmt"

type UnionFind struct {
	parent []int
	rank   []int
	size   []int
	count  int
}

func New(n int) *UnionFind {
	if n < 0 {
		panic("unionfind: negative size")
	}

	uf := &UnionFind{
		parent: make([]int, n),
		rank:   make([]int, n),
		size:   make([]int, n),
		count:  n,
	}

	for i := 0; i < n; i++ {
		uf.parent[i] = i
		uf.size[i] = 1
	}

	return uf
}

func (uf *UnionFind) Find(x int) int {
	uf.mustBeValid(x)

	root := x
	for uf.parent[root] != root {
		root = uf.parent[root]
	}

	// Path compression.
	for uf.parent[x] != x {
		next := uf.parent[x]
		uf.parent[x] = root
		x = next
	}

	return root
}

func (uf *UnionFind) Union(a, b int) bool {
	ra := uf.Find(a)
	rb := uf.Find(b)

	if ra == rb {
		return false
	}

	// Union by rank.
	if uf.rank[ra] < uf.rank[rb] {
		ra, rb = rb, ra
	}

	uf.parent[rb] = ra
	uf.size[ra] += uf.size[rb]

	if uf.rank[ra] == uf.rank[rb] {
		uf.rank[ra]++
	}

	uf.count--
	return true
}

func (uf *UnionFind) Connected(a, b int) bool {
	return uf.Find(a) == uf.Find(b)
}

func (uf *UnionFind) Count() int {
	return uf.count
}

func (uf *UnionFind) Size(x int) int {
	root := uf.Find(x)
	return uf.size[root]
}

func (uf *UnionFind) mustBeValid(x int) {
	if x < 0 || x >= len(uf.parent) {
		panic(fmt.Sprintf(
			"unionfind: index %d out of range [0, %d)",
			x, len(uf.parent),
		))
	}
}
