messages.content:
# Rust Ring Buffer with Overwrite-on-Full Semantics

Below is a fixed-capacity ring buffer suitable for audio samples (or any type). When full, `push` overwrites the oldest sample and returns it. A zero-capacity buffer is supported: `push` simply discards the value and returns it as "overwritten".

```rust
pub struct RingBuffer<T> {
    buf: Vec<Option<T>>,
    head: usize, // index of the oldest element
    len: usize,
}

impl<T> RingBuffer<T> {
    /// Creates a new ring buffer with the given capacity.
    pub fn new(capacity: usize) -> Self {
        let mut buf = Vec::with_capacity(capacity);
        buf.resize_with(capacity, || None);
        Self { buf, head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.buf.len()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// A zero-capacity buffer is considered always full.
    pub fn is_full(&self) -> bool {
        self.len == self.buf.len()
    }

    /// Pushes a sample. If the buffer is full, the oldest sample is
    /// overwritten and returned. Otherwise returns `None`.
    ///
    /// For a zero-capacity buffer, the pushed value is returned immediately.
    pub fn push(&mut self, sample: T) -> Option<T> {
        let cap = self.buf.len();
        if cap == 0 {
            return Some(sample);
        }
        if self.len < cap {
            let idx = (self.head + self.len) % cap;
            self.buf[idx] = Some(sample);
            self.len += 1;
            None
        } else {
            let old = self.buf[self.head].take();
            self.buf[self.head] = Some(sample);
            self.head = (self.head + 1) % cap;
            old
        }
    }

    /// Removes and returns the oldest sample, or `None` if empty.
    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let cap = self.buf.len();
        let old = self.buf[self.head].take();
        self.head = (self.head + 1) % cap;
        self.len -= 1;
        old
    }

    /// Returns a reference to the oldest sample without removing it.
    pub fn peek(&self) -> Option<&T> {
        if self.len == 0 {
            return None;
        }
        self.buf[self.head].as_ref()
    }

    /// Clears the buffer, preserving its capacity.
    pub fn clear(&mut self) {
        for slot in self.buf.iter_mut() {
            *slot = None;
        }
        self.head = 0;
        self.len = 0;
    }
}

impl<T: Copy> RingBuffer<T> {
    /// Iterates over the samples from oldest to newest.
    pub fn iter(&self) -> impl Iterator<Item = T> + '_ {
        let cap = self.buf.len();
        (0..self.len).map(move |i| {
            let idx = (self.head + i) % cap;
            self.buf[idx].unwrap()
        })
    }
}
```

## Unit Tests

```rust
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_buffer_is_empty() {
        let rb: RingBuffer<f32> = RingBuffer::new(4);
        assert_eq!(rb.len(), 0);
        assert!(rb.is_empty());
        assert!(!rb.is_full());
        assert_eq!(rb.capacity(), 4);
        assert_eq!(rb.peek(), None);
    }

    #[test]
    fn pop_empty_returns_none() {
        let mut rb: RingBuffer<f32> = RingBuffer::new(4);
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn push_pop_fifo() {
        let mut rb = RingBuffer::new(3);
        assert_eq!(rb.push(1.0), None);
        assert_eq!(rb.push(2.0), None);
        assert_eq!(rb.push(3.0), None);
        assert!(rb.is_full());
        assert_eq!(rb.len(), 3);

        assert_eq!(rb.pop(), Some(1.0));
        assert_eq!(rb.pop(), Some(2.0));
        assert_eq!(rb.pop(), Some(3.0));
        assert_eq!(rb.pop(), None);
        assert!(rb.is_empty());
    }

    #[test]
    fn overwrite_oldest_when_full() {
        let mut rb = RingBuffer::new(3);
        rb.push(1.0);
        rb.push(2.0);
        rb.push(3.0);

        assert_eq!(rb.push(4.0), Some(1.0));
        assert_eq!(rb.len(), 3);
        assert_eq!(rb.iter().collect::<Vec<_>>(), vec![2.0, 3.0, 4.0]);

        assert_eq!(rb.push(5.0), Some(2.0));
        assert_eq!(rb.iter().collect::<Vec<_>>(), vec![3.0, 4.0, 5.0]);
    }

    #[test]
    fn wrap_around_with_pop_and_push() {
        let mut rb = RingBuffer::new(3);
        rb.push(1.0);
        rb.push(2.0);
        rb.push(3.0);

        assert_eq!(rb.pop(), Some(1.0));
        assert_eq!(rb.push(4.0), None);
        assert_eq!(rb.iter().collect::<Vec<_>>(), vec![2.0, 3.0, 4.0]);

        assert_eq!(rb.pop(), Some(2.0));
        assert_eq!(rb.pop(), Some(3.0));
        assert_eq!(rb.pop(), Some(4.0));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn peek_does_not_remove() {
        let mut rb = RingBuffer::new(2);
        assert_eq!(rb.peek(), None);

        rb.push(1.0);
        assert_eq!(rb.peek(), Some(&1.0));
        assert_eq!(rb.len(), 1);

        rb.push(2.0);
        assert_eq!(rb.peek(), Some(&1.0));

        rb.push(3.0); // overwrites 1.0
        assert_eq!(rb.peek(), Some(&2.0));
    }

    #[test]
    fn clear_resets_buffer() {
        let mut rb = RingBuffer::new(3);
        rb.push(1.0);
        rb.push(2.0);
        rb.push(3.0);

        rb.clear();
        assert_eq!(rb.len(), 0);
        assert!(rb.is_empty());
        assert!(!rb.is_full());
        assert_eq!(rb.pop(), None);
        assert_eq!(rb.peek(), None);

        rb.push(9.0);
        assert_eq!(rb.pop(), Some(9.0));
    }

    #[test]
    fn zero_capacity() {
        let mut rb: RingBuffer<f32> = RingBuffer::new(0);
        assert_eq!(rb.capacity(), 0);
        assert_eq!(rb.len(), 0);
        assert!(rb.is_empty());
        // A zero-capacity buffer is always full.
        assert!(rb.is_full());

        assert_eq!(rb.pop(), None);
        assert_eq!(rb.peek(), None);
        // The value is immediately discarded.
        assert_eq!(rb.push(1.0), Some(1.0));
        assert_eq!(rb.len(), 0);
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn capacity_one() {
        let mut rb = RingBuffer::new(1);
        assert_eq!(rb.push(1.0), None);
        assert!(rb.is_full());

        assert_eq!(rb.push(2.0), Some(1.0));
        assert_eq!(rb.pop(), Some(2.0));
        assert_eq!(rb.pop(), None);
    }

    #[test]
    fn many_wraps() {
        let mut rb = RingBuffer::new(2);
        for i in 0..10 {
            rb.push(i as f32);
            if i % 3 == 0 {
                rb.pop();
            }
        }
        assert!(rb.len() <= rb.capacity());
        // Drain whatever remains.
        while let Some(_) = rb.pop() {}
        assert!(rb.is_empty());
    }

    #[test]
    fn works_with_non_float_copy_types() {
        let mut rb = RingBuffer::new(2);
        assert_eq!(rb.push(10u32), None);
        assert_eq!(rb.push(20u32), None);
        assert_eq!(rb.push(30u32), Some(10u32));
        assert_eq!(rb.pop(), Some(20u32));
        assert_eq!(rb.pop(), Some(30u32));
        assert_eq!(rb.pop(), None);
    }
}
```

## Notes on Design Choices

- **Generic over `T`** so it works for `f32`, `i16`, or any other sample type. `iter` requires `T: Copy`, which is true for all audio sample types in practice.
- **Zero-capacity support**: `push` returns `Some(sample)` because there is nothing to overwrite — the value is discarded immediately. `is_full()` returns `true` since `len == capacity == 0`.
- **`push` returns the overwritten value** rather than silently discarding it, giving the caller the option to handle the dropped sample (e.g., for metering or diagnostics).
- **No `unsafe` code** is used; `Option<T>` slots make initialization and clearing straightforward.
- **FIFO ordering** is preserved for both `pop` and `iter`.

