            let idx = (self.head + self.len) % cap;
            self.buf[idx] = Some(sample);
            self.len += 1;
            None
        } else {
            let old = self.buf[self.head].take();
            self.buf[self.head] = Some(sample);
            self.head = (self.head + 1) % cap;
            old
        }
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let cap = self.buf.len();
        let old = self.buf[self.head].take();
        self.head = (self.head + 1) % cap;
        self.len -= 1;
        old
    }
}
