package main

import "fmt"

// MinHeap is an integer min-heap.
type MinHeap struct {
	data []int
}

func NewMinHeap() *MinHeap {
	return &MinHeap{}
}

func (h *MinHeap) Len() int {
	return len(h.data)
}

func (h *MinHeap) Peek() (int, bool) {
	if len(h.data) == 0 {
		return 0, false
	}
	return h.data[0], true
}

func (h *MinHeap) Push(value int) {
	h.data = append(h.data, value)
	h.up(len(h.data) - 1)
}

func (h *MinHeap) Pop() (int, bool) {
	if len(h.data) == 0 {
		return 0, false
	}

	last := len(h.data) - 1
	h.swap(0, last)

	value := h.data[last]
	h.data = h.data[:last]

	if len(h.data) > 0 {
		h.down(0)
	}

	return value, true
}

// Heapify turns the current slice into a valid min-heap.
func (h *MinHeap) Heapify() {
	for i := len(h.data)/2 - 1; i >= 0; i-- {
		h.down(i)
	}
}

func (h *MinHeap) up(i int) {
	for i > 0 {
		parent := (i - 1) / 2
		if h.data[parent] <= h.data[i] {
			break
		}
		h.swap(parent, i)
		i = parent
	}
}

func (h *MinHeap) down(i int) {
	n := len(h.data)

	for {
		left := 2*i + 1
		if left >= n {
			break
		}

		smallest := left
		right := left + 1

		if right < n && h.data[right] < h.data[left] {
			smallest = right
		}

		if h.data[i] <= h.data[smallest] {
			break
		}

		h.swap(i, smallest)
		i = smallest
	}
}

func (h *MinHeap) swap(i, j int) {
	h.data[i], h.data[j] = h.data[j], h.data[i]
}

func NewMinHeapFromSlice(values []int) *MinHeap {
	copied := append([]int(nil), values...)
	h := &MinHeap{data: copied}
	h.Heapify()
	return h
}

func main() {
	h := NewMinHeap()

	h.Push(5)
	h.Push(2)
	h.Push(8)
	h.Push(1)
	h.Push(3)

	fmt.Println(h.Peek()) // 1 true

	for h.Len() > 0 {
		v, _ := h.Pop()
		fmt.Print(v, " ")
	}
	fmt.Println() // 1 2 3 5 8

	h2 := NewMinHeapFromSlice([]int{9, 4, 7, 1, 3, 8, 2})
	for h2.Len() > 0 {
		v, _ := h2.Pop()
		fmt.Print(v, " ")
	}
	fmt.Println() // 1 2 3 4 7 8 9
}
