```python
def longest_common_subsequence(a: str, b: str) -> str:
    """
    Return one longest common subsequence of strings a and b.

    A subsequence is obtained by deleting zero or more characters
    without changing the order of the remaining characters.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Reconstruct one LCS.
    i = j = 0
    result = []

    while i < m and j < n:
        if a[i] == b[j]:
            result.append(a[i])
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            i += 1
        else:
            j += 1

    return "".join(result)


if __name__ == "__main__":
    import unittest

    class TestLongestCommonSubsequence(unittest.TestCase):
        def test_both_empty(self):
            self.assertEqual(longest_common_subsequence("", ""), "")

        def test_first_empty(self):
            self.assertEqual(longest_common_subsequence("", "abc"), "")

        def test_second_empty(self):
            self.assertEqual(longest_common_subsequence("abc", ""), "")

        def test_no_common_characters(self):
            self.assertEqual(longest_common_subsequence("abc", "def"), "")

        def test_identical_strings(self):
            self.assertEqual(longest_common_subsequence("abc", "abc"), "abc")

        def test_single_char_match(self):
            self.assertEqual(longest_common_subsequence("a", "a"), "a")

        def test_single_char_no_match(self):
            self.assertEqual(longest_common_subsequence("a", "b"), "")

        def test_one_string_is_subsequence(self):
            self.assertEqual(longest_common_subsequence("abcde", "ace"), "ace")

        def test_standard_example(self):
            self.assertEqual(
                longest_common_subsequence("AGGTAB", "GXTXAYB"),
                "GTAB",
            )

        def test_repeated_characters(self):
            self.assertEqual(longest_common_subsequence("aaaa", "aa"), "aa")

        def test_case_sensitive(self):
            self.assertEqual(longest_common_subsequence("abc", "ABC"), "")

        def test_multiple_valid_lcs(self):
            # "ABAB" and "BABA" have multiple LCS values, e.g. "ABA" and "BAB".
            result = longest_common_subsequence("ABAB", "BABA")
            self.assertEqual(len(result), 3)
            self.assertIn(result, {"ABA", "BAB"})

        def test_lcs_characters_remain_in_order(self):
            result = longest_common_subsequence("XMJYAUZ", "MZJAWXU")
            self.assertEqual(len(result), 4)
            self.assertIn(result, {"MJAU"})

    unittest.main()
